-- AlzaHR Client Portal: newsletters (Manager Minute, The Pause)
-- Run once in Supabase → SQL Editor → New query → Run. Safe to re-run.
--
-- Ben queues, edits and copies each issue in the console. Clients only see an issue
-- after Ben saves it to their Library.

create table if not exists public.newsletters (
  id text primary key,
  client_id text not null references public.clients(id) on delete cascade,
  data jsonb not null,
  created_by text not null default public.me_email(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists newsletters_client_idx on public.newsletters (client_id);

drop trigger if exists newsletters_touch on public.newsletters;
create trigger newsletters_touch before update on public.newsletters for each row execute function public.touch();

alter table public.newsletters enable row level security;
drop policy if exists newsletters_read on public.newsletters;
drop policy if exists newsletters_write on public.newsletters;
-- Ben sees everything; a client's people see only issues saved to their Library
create policy newsletters_read on public.newsletters for select
  using (public.is_advisor() or (public.is_member(client_id) and coalesce((data->>'inLibrary')::boolean, false)));
create policy newsletters_write on public.newsletters for all
  using (public.is_advisor()) with check (public.is_advisor());

-- ---------------------------------------------------------------- September and October issues
-- Brought over from the Pause Send Console (with the edits saved there). Skipped if the client isn't in the portal.
do $$
declare cid text;
begin
  select id into cid from public.clients where lower(name) like '%presidio%' or lower(name) like '%main post%' limit 1;
  if cid is not null then
    insert into public.newsletters (id, client_id, created_by, data)
    values ('nl-2026-09-presidio-manager-minute-en', cid, 'ben@alzapc.com', $nl${"kind": "manager-minute", "month": "2026-09", "lang": "en", "subject": "Manager Minute: Get your team clear for the year-end push", "preview": "One 5-minute conversation that gets everyone clear before the end of the year.", "sendFrom": "Pendolino (ben@pendolinogroup.com)", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Get your team clear for the year-end push</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One 5-minute conversation that gets everyone clear before the end of the year.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#8C2926\" style=\"background:#8C2926;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#F1D9D8;font-weight:bold;\">Presidio Bay &amp; The Main Post<br><span style=\"font-weight:normal;\">September 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#F1D9D8;\">This month: Priorities</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Clear the fog before the year-end push</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-left:4px solid #8C2926;padding:16px 20px;\"><p style=\"margin:0 0 6px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Welcome</p><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">This is the first Manager Minute. Once a month you&#x27;ll get a quick, practical read on one real situation you&#x27;ll probably recognize, the words to use, and one small move to try that week. It&#x27;s short on purpose. Pick one thing and put it to work.</p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">-Ben</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;If there is any one “secret” of effectiveness, it is concentration. Effective executives do first things first and they do one thing at a time.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Peter F. Drucker, The Effective Executive</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">The year is winding down. Someone on your team is working two deals, an investor update, and year-end reporting at the same time. Every request feels urgent, and they&#x27;re quietly working late to keep up. You haven&#x27;t said what matters most.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#8C2926;\">Why it matters.</b> Gallup found only 46% of U.S. employees clearly know what&#x27;s expected of them at work, down from 56% in 2020. When the calendar fills up, that number doesn&#x27;t fix itself.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;I know everything feels urgent right now. Let&#x27;s take five minutes and get clear on what matters most, and what can wait.&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Everything&#x27;s a priority right now.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8C2926;\">Say this:</b> If you only get three things done this month, make it these.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Just figure it out.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8C2926;\">Say this:</b> Here&#x27;s what done looks like. What do you need from me to get there?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Can you get to all of these by Friday?</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8C2926;\">Say this:</b> The investor update comes first. The rest can wait until next week.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">In California, nonexempt employees get a 30-minute meal break before the end of their fifth hour of work, plus a paid 10-minute rest break for every four hours. Rest breaks have to be truly off duty. Miss one and the company owes an extra hour of pay for each day it happens. When the calendar fills up, breaks are usually the first thing to slip. Protect them.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #8C2926;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Before the end of the month, grab 5 minutes with each person on your team and ask three questions: Are you clear on your priorities? Is anything blocking you, or is there something we should stop doing? How can I help?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to Ben anytime at <a href=\"mailto:ben@presidiobay.com\" style=\"color:#8C2926;font-weight:bold;\">ben@presidiobay.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://www.taylorfrancis.com/chapters/mono/10.4324/9780080549354-5/first-things-first-peter-drucker\" style=\"color:#707070;\">Drucker</a> &middot; <a href=\"https://www.gallup.com/workplace/654911/employee-engagement-sinks-year-low.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_mealperiods.htm\" style=\"color:#707070;\">Cal. DIR: meal periods</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_restperiods.htm\" style=\"color:#707070;\">Cal. DIR: rest periods</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Get your team clear for the year-end push</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One 5-minute conversation that gets everyone clear before the end of the year.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#8C2926\" style=\"background:#8C2926;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12