  if cid is not null then
    insert into public.newsletters (id, client_id, created_by, data)
    values ('nl-2026-09-hensley-manager-minute-en-es', cid, 'ben@alzapc.com', $nl${"kind": "manager-minute", "month": "2026-09", "lang": "en+es", "subject": "Manager Minute: Get your team clear for the year-end push | Minuto del Líder (English / Español)", "preview": "One 5-minute conversation that gets everyone clear before the end of the year. Versión en español incluida.", "sendFrom": "hr@blueprintstudios.com", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Get your team clear for the year-end push | Minuto del Líder</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One 5-minute conversation that gets everyone clear before the end of the year. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#231F20\" style=\"background:#231F20;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#C3922F;font-weight:bold;\">Hensley Event Resources<br><span style=\"font-weight:normal;\">September 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C3922F;\">This month: Priorities</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Clear the fog before the year-end push</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#8F6A1C;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-left:4px solid #C3922F;padding:16px 20px;\"><p style=\"margin:0 0 6px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Welcome</p><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">This is the first Manager Minute. Once a month you&#x27;ll get a quick, practical read on one real situation you&#x27;ll probably recognize, the words to use, and one small move to try that week. It&#x27;s short on purpose. Pick one thing and put it to work.</p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">-Ben</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;If there is any one “secret” of effectiveness, it is concentration. Effective executives do first things first and they do one thing at a time.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Peter F. Drucker, The Effective Executive</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">The end of the year is your busiest stretch. Your warehouse lead is juggling three holiday installs, a new inventory process, and a crew that&#x27;s short two people. Everything feels urgent, and nobody&#x27;s sure what comes first. If you&#x27;re honest, you&#x27;re not either.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#8F6A1C;\">Why it matters.</b> Gallup found only 46% of U.S. employees clearly know what&#x27;s expected of them at work, down from 56% in 2020. When the calendar fills up, that number doesn&#x27;t fix itself.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;I know everything feels urgent right now. Let&#x27;s take five minutes and get clear on what matters most, and what can wait.&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Everything&#x27;s a priority right now.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Say this:</b> If you only get three things done this month, make it these.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Just figure it out.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Say this:</b> Here&#x27;s what done looks like. What do you need from me to get there?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Just make it work.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Say this:</b> All three installs are happening on schedule. The new inventory process can wait until January. What do you need from me to cover the crew?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">In California, nonexempt employees get a 30-minute meal break before the end of their fifth hour of work, plus a paid 10-minute rest break for every four hours. Rest breaks have to be truly off duty. Miss one and the company owes an extra hour of pay for each day it happens. When the calendar fills up, breaks are usually the first thing to slip. Protect them.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #C3922F;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Before the end of the month, grab 5 minutes with each person on your team and ask three questions: Are you clear on your priorities? Is anything blocking you, or is there something we should stop doing? How can I help?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to Ben anytime at <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#8F6A1C;font-weight:bold;\">ben@pendolinogroup.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://www.taylorfrancis.com/chapters/mono/10.4324/9780080549354-5/first-things-first-peter-drucker\" style=\"color:#707070;\">Drucker</a> &middot; <a href=\"https://www.gallup.com/workplace/654911/employee-engagement-sinks-year-low.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_mealperiods.htm\" style=\"color:#707070;\">Cal. DIR: meal periods</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_restperiods.htm\" style=\"color:#707070;\">Cal. DIR: rest periods</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #231F20;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Versión en español</p><h2 style=\"margin:6px 0 0 0;font-family:Georgia, 'Times New Roman', serif;font-size:28px;font-weight:normal;line-height:1.2;color:#2B2B2B;\">Minuto del Líder: Aclara el panorama antes del cierre de año</h2></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-left:4px solid #C3922F;padding:16px 20px;\"><p style=\"margin:0 0 6px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Bienvenida</p><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Este es el primer Minuto del Líder. Una vez al mes vas a recibir una lectura rápida y práctica sobre una situación real que seguramente vas a reconocer, las palabras para usar y una acción pequeña para esa semana. Es corto a propósito. Elige una cosa y ponla en práctica.</p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">-Ben</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Si hay un “secreto” de la efectividad, es la concentración. Los ejecutivos efectivos hacen primero lo primero, y hacen una cosa a la vez.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Peter F. Drucker, The Effective Executive (traducción)</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">El cierre de año es tu temporada más pesada. Tu líder de almacén está haciendo malabares con tres instalaciones navideñas, un nuevo proceso de inventario y una cuadrilla a la que le faltan dos personas. Todo se siente urgente y nadie sabe qué va primero. Si eres honesto, tú tampoco.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#8F6A1C;\">Por qué importa.</b> Gallup encontró que solo el 46% de los empleados en EE. UU. sabe con claridad qué se espera de ellos en el trabajo, frente al 56% en 2020. Cuando la agenda se llena, ese número no mejora solo.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Qué decir</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;Sé que ahorita todo se siente urgente. Tomemos cinco minutos para aclarar qué es lo más importante y qué puede esperar.&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Líder vs. jefe</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Ahorita todo es prioridad.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Di esto:</b> Si este mes solo logras tres cosas, que sean estas.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Nada más resuélvelo.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Di esto:</b> Así se ve terminado. ¿Qué necesitas de mí para llegar ahí?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Nada más haz que funcione.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Di esto:</b> Las tres instalaciones van en la fecha. El nuevo proceso de inventario puede esperar a enero. ¿Qué necesitas de mí para cubrir la cuadrilla?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Lo que debes saber</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">En California, los empleados no exentos tienen derecho a un descanso de 30 minutos para comer antes de terminar su quinta hora de trabajo, y a un descanso pagado de 10 minutos por cada cuatro horas. Los descansos deben ser realmente libres de trabajo. Si se pierde uno, la empresa debe una hora extra de pago por cada día que pase. Cuando la agenda se llena, los descansos suelen ser lo primero que se sacrifica. Protégelos.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #C3922F;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Tu acción de 5 minutos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Antes de que termine el mes, toma 5 minutos con cada persona de tu equipo y hazle tres preguntas: ¿Tienes claras tus prioridades? ¿Hay algo que te esté frenando o algo que deberíamos dejar de hacer? ¿Cómo te puedo ayudar?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">¿Preguntas o algo con tu equipo que quieras conversar? Escríbele a Ben cuando quieras a <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#8F6A1C;font-weight:bold;\">ben@pendolinogroup.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Fuentes: <a href=\"https://www.taylorfrancis.com/chapters/mono/10.4324/9780080549354-5/first-things-first-peter-drucker\" style=\"color:#707070;\">Drucker</a> &middot; <a href=\"https://www.gallup.com/workplace/654911/employee-engagement-sinks-year-low.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_mealperiods.htm\" style=\"color:#707070;\">Cal. DIR: meal periods</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_restperiods.htm\" style=\"color:#707070;\">Cal. DIR: rest periods</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Get your team clear for the year-end push | Minuto del Líder</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One 5-minute conversation that gets everyone clear before the end of the year. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#231F20\" style=\"background:#231F20;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#C3922F;font-weight:bold;\">Hensley Event Resources<br><span style=\"font-weight:normal;\">September 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C3922F;\">This month: Priorities</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Clear the fog before the year-end push</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#8F6A1C;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-left:4px solid #C3922F;padding:16px 20px;\"><p style=\"margin:0 0 6px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Welcome</p><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">This is the first Manager Minute. Once a month you&#x27;ll get a quick, practical read on one real situation you&#x27;ll probably recognize, the words to use, and one small move to try that week. It&#x27;s short on purpose. Pick one thing and put it to work.</p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">-Ben</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;If there is any one “secret” of effectiveness, it is concentration. Effective executives do first things first and they do one thing at a time.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Peter F. Drucker, The Effective Executive</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">The end of the year is your busiest stretch. Your warehouse lead is juggling three holiday installs, a new inventory process, and a crew that&#x27;s short two people. Everything feels urgent, and nobody&#x27;s sure what comes first. If you&#x27;re honest, you&#x27;re not either.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#8F6A1C;\">Why it matters.</b> Gallup found only 46% of U.S. employees clearly know what&#x27;s expected of them at work, down from 56% in 2020. When the calendar fills up, that number doesn&#x27;t fix itself.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;I know everything feels urgent right now. Let&#x27;s take five minutes and get clear on what matters most, and what can wait.&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Everything&#x27;s a priority right now.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Say this:</b> If you only get three things done this month, make it these.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Just figure it out.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Say this:</b> Here&#x27;s what done looks like. What do you need from me to get there?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Just make it work.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Say this:</b> All three installs are happening on schedule. The new inventory process can wait until January. What do you need from me to cover the crew?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">In California, nonexempt employees get a 30-minute meal break before the end of their fifth hour of work, plus a paid 10-minute rest break for every four hours. Rest breaks have to be truly off duty. Miss one and the company owes an extra hour of pay for each day it happens. When the calendar fills up, breaks are usually the first thing to slip. Protect them.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #C3922F;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Before the end of the month, grab 5 minutes with each person on your team and ask three questions: Are you clear on your priorities? Is anything blocking you, or is there something we should stop doing? How can I help?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to Ben anytime at <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#8F6A1C;font-weight:bold;\">ben@pendolinogroup.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://www.taylorfrancis.com/chapters/mono/10.4324/9780080549354-5/first-things-first-peter-drucker\" style=\"color:#707070;\">Drucker</a> &middot; <a href=\"https://www.gallup.com/workplace/654911/employee-engagement-sinks-year-low.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_mealperiods.htm\" style=\"color:#707070;\">Cal. DIR: meal periods</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_restperiods.htm\" style=\"color:#707070;\">Cal. DIR: rest periods</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #231F20;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Versión en español</p><h2 style=\"margin:6px 0 0 0;font-family:Georgia, 'Times New Roman', serif;font-size:28px;font-weight:normal;line-height:1.2;color:#2B2B2B;\">Minuto del Líder: Aclara el panorama antes del cierre de año</h2></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-left:4px solid #C3922F;padding:16px 20px;\"><p style=\"margin:0 0 6px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Bienvenida</p><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Este es el primer Minuto del Líder. Una vez al mes vas a recibir una lectura rápida y práctica sobre una situación real que seguramente vas a reconocer, las palabras para usar y una acción pequeña para esa semana. Es corto a propósito. Elige una cosa y ponla en práctica.</p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">-Ben</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Si hay un “secreto” de la efectividad, es la concentración. Los ejecutivos efectivos hacen primero lo primero, y hacen una cosa a la vez.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Peter F. Drucker, The Effective Executive (traducción)</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">El cierre de año es tu temporada más pesada. Tu líder de almacén está haciendo malabares con tres instalaciones navideñas, un nuevo proceso de inventario y una cuadrilla a la que le faltan dos personas. Todo se siente urgente y nadie sabe qué va primero. Si eres honesto, tú tampoco.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#8F6A1C;\">Por qué importa.</b> Gallup encontró que solo el 46% de los empleados en EE. UU. sabe con claridad qué se espera de ellos en el trabajo, frente al 56% en 2020. Cuando la agenda se llena, ese número no mejora solo.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Qué decir</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;Sé que ahorita todo se siente urgente. Tomemos cinco minutos para aclarar qué es lo más importante y qué puede esperar.&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Líder vs. jefe</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Ahorita todo es prioridad.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Di esto:</b> Si este mes solo logras tres cosas, que sean estas.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Nada más resuélvelo.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Di esto:</b> Así se ve terminado. ¿Qué necesitas de mí para llegar ahí?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Nada más haz que funcione.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Di esto:</b> Las tres instalaciones van en la fecha. El nuevo proceso de inventario puede esperar a enero. ¿Qué necesitas de mí para cubrir la cuadrilla?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Lo que debes saber</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">En California, los empleados no exentos tienen derecho a un descanso de 30 minutos para comer antes de terminar su quinta hora de trabajo, y a un descanso pagado de 10 minutos por cada cuatro horas. Los descansos deben ser realmente libres de trabajo. Si se pierde uno, la empresa debe una hora extra de pago por cada día que pase. Cuando la agenda se llena, los descansos suelen ser lo primero que se sacrifica. Protégelos.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #C3922F;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Tu acción de 5 minutos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Antes de que termine el mes, toma 5 minutos con cada persona de tu equipo y hazle tres preguntas: ¿Tienes claras tus prioridades? ¿Hay algo que te esté frenando o algo que deberíamos dejar de hacer? ¿Cómo te puedo ayudar?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">¿Preguntas o algo con tu equipo que quieras conversar? Escríbele a Ben cuando quieras a <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#8F6A1C;font-weight:bold;\">ben@pendolinogroup.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Fuentes: <a href=\"https://www.taylorfrancis.com/chapters/mono/10.4324/9780080549354-5/first-things-first-peter-drucker\" style=\"color:#707070;\">Drucker</a> &middot; <a href=\"https://www.gallup.com/workplace/654911/employee-engagement-sinks-year-low.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_mealperiods.htm\" style=\"color:#707070;\">Cal. DIR: meal periods</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_restperiods.htm\" style=\"color:#707070;\">Cal. DIR: rest periods</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Hensley Event Resources", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
    on conflict (id) do nothing;
  end if;
  select id into cid from public.clients where lower(name) = 'blueprint studios' limit 1;
  if cid is not null then
    insert into public.newsletters (id, client_id, created_by, data)
    values ('nl-2026-09-blueprint-manager-minute-en-es', cid, 'ben@alzapc.com', $nl${"kind": "manager-minute", "month": "2026-09", "lang": "en+es", "subject": "Manager Minute: Get your team clear for the year-end push | Minuto del Líder (English / Español)", "preview": "One 5-minute conversation that gets everyone clear before the end of the year. Versión en español incluida.", "sendFrom": "hr@blueprintstudios.com", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Get your team clear for the year-end push | Minuto del Líder</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One 5-minute conversation that gets everyone clear before the end of the year. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#C9D4FF;font-weight:bold;\">Blueprint Studios<br><span style=\"font-weight:normal;\">September 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C9D4FF;\">This month: Priorities</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Clear the fog before the year-end push</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#1740F5;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-left:4px solid #1740F5;padding:16px 20px;\"><p style=\"margin:0 0 6px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Welcome</p><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">This is the first Manager Minute. Once a month you&#x27;ll get a quick, practical read on one real situation you&#x27;ll probably recognize, the words to use, and one small move to try that week. It&#x27;s short on purpose. Pick one thing and put it to work.</p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">-Ben and Nelda</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;If there is any one “secret” of effectiveness, it is concentration. Effective executives do first things first and they do one thing at a time.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Peter F. Drucker, The Effective Executive</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">The end of the year is your busiest stretch. Your warehouse lead is juggling three holiday installs, a new inventory process, and a crew that&#x27;s short two people. Everything feels urgent, and nobody&#x27;s sure what comes first. If you&#x27;re honest, you&#x27;re not either.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#1740F5;\">Why it matters.</b> Gallup found only 46% of U.S. employees clearly know what&#x27;s expected of them at work, down from 56% in 2020. When the calendar fills up, that number doesn&#x27;t fix itself.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;I know everything feels urgent right now. Let&#x27;s take five minutes and get clear on what matters most, and what can wait.&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Everything&#x27;s a priority right now.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Say this:</b> If you only get three things done this month, make it these.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Just figure it out.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Say this:</b> Here&#x27;s what done looks like. What do you need from me to get there?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Just make it work.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Say this:</b> All three installs are happening on schedule. The new inventory process can wait until January. What do you need from me to cover the crew?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">California and Nevada both require breaks for nonexempt employees. California: a 30-minute meal break before the end of the fifth hour, plus a paid 10-minute rest break every four hours, and a missed break costs an extra hour of pay. Nevada: a 30-minute meal break for any 8 continuous hours, plus a paid 10-minute rest break every four hours (NRS 608.019). When the calendar fills up, breaks are usually the first thing to slip. Protect them.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #1740F5;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Before the end of the month, grab 5 minutes with each person on your team and ask three questions: Are you clear on your priorities? Is anything blocking you, or is there something we should stop doing? How can I help?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:20px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;padding:18px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Recognize your people</p><p style=\"margin:0 0 14px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Someone on your team go above and beyond? Give them a shout-out. It takes a minute, and they&#x27;ll get an email letting them know.</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:10px 18px;\"><a href=\"https://docs.google.com/forms/d/e/1FAIpQLSce5Ey8EsvNqU6S9rSY5aC7DPxCE15Gsf1r5LPE-9iWkOyFGQ/viewform?usp=dialog\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:14px;font-weight:bold;color:#FFFFFF;text-decoration:none;\">Recognize someone &rarr;</a></td></tr></table></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to HR anytime at <a href=\"mailto:hr@blueprintstudios.com\" style=\"color:#1740F5;font-weight:bold;\">hr@blueprintstudios.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://www.taylorfrancis.com/chapters/mono/10.4324/9780080549354-5/first-things-first-peter-drucker\" style=\"color:#707070;\">Drucker</a> &middot; <a href=\"https://www.gallup.com/workplace/654911/employee-engagement-sinks-year-low.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_mealperiods.htm\" style=\"color:#707070;\">Cal. DIR: meal periods</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_restperiods.htm\" style=\"color:#707070;\">Cal. DIR: rest periods</a> &middot; <a href=\"https://www.leg.state.nv.us/nrs/nrs-608.html\" style=\"color:#707070;\">Nev. Rev. Stat. 608.019</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #1740F5;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Versión en español</p><h2 style=\"margin:6px 0 0 0;font-family:Georgia, 'Times New Roman', serif;font-size:28px;font-weight:normal;line-height:1.2;color:#2B2B2B;\">Minuto del Líder: Aclara el panorama antes del cierre de año</h2></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-left:4px solid #1740F5;padding:16px 20px;\"><p style=\"margin:0 0 6px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Bienvenida</p><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Este es el primer Minuto del Líder. Una vez al mes vas a recibir una lectura rápida y práctica sobre una situación real que seguramente vas a reconocer, las palabras para usar y una acción pequeña para esa semana. Es corto a propósito. Elige una cosa y ponla en práctica.</p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">-Ben y Nelda</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Si hay un “secreto” de la efectividad, es la concentración. Los ejecutivos efectivos hacen primero lo primero, y hacen una cosa a la vez.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Peter F. Drucker, The Effective Executive (traducción)</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">El cierre de año es tu temporada más pesada. Tu líder de almacén está haciendo malabares con tres instalaciones navideñas, un nuevo proceso de inventario y una cuadrilla a la que le faltan dos personas. Todo se siente urgente y nadie sabe qué va primero. Si eres honesto, tú tampoco.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#1740F5;\">Por qué importa.</b> Gallup encontró que solo el 46% de los empleados en EE. UU. sabe con claridad qué se espera de ellos en el trabajo, frente al 56% en 2020. Cuando la agenda se llena, ese número no mejora solo.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Qué decir</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;Sé que ahorita todo se siente urgente. Tomemos cinco minutos para aclarar qué es lo más importante y qué puede esperar.&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Líder vs. jefe</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Ahorita todo es prioridad.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Di esto:</b> Si este mes solo logras tres cosas, que sean estas.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Nada más resuélvelo.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Di esto:</b> Así se ve terminado. ¿Qué necesitas de mí para llegar ahí?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Nada más haz que funcione.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Di esto:</b> Las tres instalaciones van en la fecha. El nuevo proceso de inventario puede esperar a enero. ¿Qué necesitas de mí para cubrir la cuadrilla?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Lo que debes saber</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">California y Nevada exigen descansos para los empleados no exentos. California: 30 minutos para comer antes de terminar la quinta hora, más un descanso pagado de 10 minutos cada cuatro horas, y un descanso perdido cuesta una hora extra de pago. Nevada: 30 minutos para comer por cada 8 horas continuas, más un descanso pagado de 10 minutos cada cuatro horas (NRS 608.019). Cuando la agenda se llena, los descansos suelen ser lo primero que se sacrifica. Protégelos.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #1740F5;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Tu acción de 5 minutos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Antes de que termine el mes, toma 5 minutos con cada persona de tu equipo y hazle tres preguntas: ¿Tienes claras tus prioridades? ¿Hay algo que te esté frenando o algo que deberíamos dejar de hacer? ¿Cómo te puedo ayudar?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:20px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;padding:18px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Reconoce a tu equipo</p><p style=\"margin:0 0 14px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">¿Alguien de tu equipo hizo algo extra? Dale un reconocimiento. Toma un minuto y le llegará un correo avisándole.</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:10px 18px;\"><a href=\"https://docs.google.com/forms/d/e/1FAIpQLSce5Ey8EsvNqU6S9rSY5aC7DPxCE15Gsf1r5LPE-9iWkOyFGQ/viewform?usp=dialog\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:14px;font-weight:bold;color:#FFFFFF;text-decoration:none;\">Reconocer a alguien &rarr;</a></td></tr></table></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">¿Preguntas o algo con tu equipo que quieras conversar? Escríbele a RR. HH. cuando quieras a <a href=\"mailto:hr@blueprintstudios.com\" style=\"color:#1740F5;font-weight:bold;\">hr@blueprintstudios.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Fuentes: <a href=\"https://www.taylorfrancis.com/chapters/mono/10.4324/9780080549354-5/first-things-first-peter-drucker\" style=\"color:#707070;\">Drucker</a> &middot; <a href=\"https://www.gallup.com/workplace/654911/employee-engagement-sinks-year-low.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_mealperiods.htm\" style=\"color:#707070;\">Cal. DIR: meal periods</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_restperiods.htm\" style=\"color:#707070;\">Cal. DIR: rest periods</a> &middot; <a href=\"https://www.leg.state.nv.us/nrs/nrs-608.html\" style=\"color:#707070;\">Nev. Rev. Stat. 608.019</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Get your team clear for the year-end push | Minuto del Líder</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One 5-minute conversation that gets everyone clear before the end of the year. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#C9D4FF;font-weight:bold;\">Blueprint Studios<br><span style=\"font-weight:normal;\">September 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C9D4FF;\">This month: Priorities</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Clear the fog before the year-end push</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#1740F5;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-left:4px solid #1740F5;padding:16px 20px;\"><p style=\"margin:0 0 6px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Welcome</p><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">This is the first Manager Minute. Once a month you&#x27;ll get a quick, practical read on one real situation you&#x27;ll probably recognize, the words to use, and one small move to try that week. It&#x27;s short on purpose. Pick one thing and put it to work.</p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">-Ben and Nelda</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;If there is any one “secret” of effectiveness, it is concentration. Effective executives do first things first and they do one thing at a time.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Peter F. Drucker, The Effective Executive</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">The end of the year is your busiest stretch. Your warehouse lead is juggling three holiday installs, a new inventory process, and a crew that&#x27;s short two people. Everything feels urgent, and nobody&#x27;s sure what comes first. If you&#x27;re honest, you&#x27;re not either.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#1740F5;\">Why it matters.</b> Gallup found only 46% of U.S. employees clearly know what&#x27;s expected of them at work, down from 56% in 2020. When the calendar fills up, that number doesn&#x27;t fix itself.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;I know everything feels urgent right now. Let&#x27;s take five minutes and get clear on what matters most, and what can wait.&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Everything&#x27;s a priority right now.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Say this:</b> If you only get three things done this month, make it these.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Just figure it out.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Say this:</b> Here&#x27;s what done looks like. What do you need from me to get there?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Just make it work.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Say this:</b> All three installs are happening on schedule. The new inventory process can wait until January. What do you need from me to cover the crew?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">California and Nevada both require breaks for nonexempt employees. California: a 30-minute meal break before the end of the fifth hour, plus a paid 10-minute rest break every four hours, and a missed break costs an extra hour of pay. Nevada: a 30-minute meal break for any 8 continuous hours, plus a paid 10-minute rest break every four hours (NRS 608.019). When the calendar fills up, breaks are usually the first thing to slip. Protect them.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #1740F5;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Before the end of the month, grab 5 minutes with each person on your team and ask three questions: Are you clear on your priorities? Is anything blocking you, or is there something we should stop doing? How can I help?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:20px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;padding:18px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Recognize your people</p><p style=\"margin:0 0 14px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Someone on your team go above and beyond? Give them a shout-out. It takes a minute, and they&#x27;ll get an email letting them know.</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:10px 18px;\"><a href=\"https://docs.google.com/forms/d/e/1FAIpQLSce5Ey8EsvNqU6S9rSY5aC7DPxCE15Gsf1r5LPE-9iWkOyFGQ/viewform?usp=dialog\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:14px;font-weight:bold;color:#FFFFFF;text-decoration:none;\">Recognize someone &rarr;</a></td></tr></table></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to HR anytime at <a href=\"mailto:hr@blueprintstudios.com\" style=\"color:#1740F5;font-weight:bold;\">hr@blueprintstudios.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://www.taylorfrancis.com/chapters/mono/10.4324/9780080549354-5/first-things-first-peter-drucker\" style=\"color:#707070;\">Drucker</a> &middot; <a href=\"https://www.gallup.com/workplace/654911/employee-engagement-sinks-year-low.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_mealperiods.htm\" style=\"color:#707070;\">Cal. DIR: meal periods</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_restperiods.htm\" style=\"color:#707070;\">Cal. DIR: rest periods</a> &middot; <a href=\"https://www.leg.state.nv.us/nrs/nrs-608.html\" style=\"color:#707070;\">Nev. Rev. Stat. 608.019</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #1740F5;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Versión en español</p><h2 style=\"margin:6px 0 0 0;font-family:Georgia, 'Times New Roman', serif;font-size:28px;font-weight:normal;line-height:1.2;color:#2B2B2B;\">Minuto del Líder: Aclara el panorama antes del cierre de año</h2></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-left:4px solid #1740F5;padding:16px 20px;\"><p style=\"margin:0 0 6px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Bienvenida</p><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Este es el primer Minuto del Líder. Una vez al mes vas a recibir una lectura rápida y práctica sobre una situación real que seguramente vas a reconocer, las palabras para usar y una acción pequeña para esa semana. Es corto a propósito. Elige una cosa y ponla en práctica.</p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">-Ben y Nelda</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Si hay un “secreto” de la efectividad, es la concentración. Los ejecutivos efectivos hacen primero lo primero, y hacen una cosa a la vez.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Peter F. Drucker, The Effective Executive (traducción)</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">El cierre de año es tu temporada más pesada. Tu líder de almacén está haciendo malabares con tres instalaciones navideñas, un nuevo proceso de inventario y una cuadrilla a la que le faltan dos personas. Todo se siente urgente y nadie sabe qué va primero. Si eres honesto, tú tampoco.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#1740F5;\">Por qué importa.</b> Gallup encontró que solo el 46% de los empleados en EE. UU. sabe con claridad qué se espera de ellos en el trabajo, frente al 56% en 2020. Cuando la agenda se llena, ese número no mejora solo.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Qué decir</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;Sé que ahorita todo se siente urgente. Tomemos cinco minutos para aclarar qué es lo más importante y qué puede esperar.&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Líder vs. jefe</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Ahorita todo es prioridad.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Di esto:</b> Si este mes solo logras tres cosas, que sean estas.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Nada más resuélvelo.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Di esto:</b> Así se ve terminado. ¿Qué necesitas de mí para llegar ahí?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Nada más haz que funcione.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Di esto:</b> Las tres instalaciones van en la fecha. El nuevo proceso de inventario puede esperar a enero. ¿Qué necesitas de mí para cubrir la cuadrilla?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Lo que debes saber</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">California y Nevada exigen descansos para los empleados no exentos. California: 30 minutos para comer antes de terminar la quinta hora, más un descanso pagado de 10 minutos cada cuatro horas, y un descanso perdido cuesta una hora extra de pago. Nevada: 30 minutos para comer por cada 8 horas continuas, más un descanso pagado de 10 minutos cada cuatro horas (NRS 608.019). Cuando la agenda se llena, los descansos suelen ser lo primero que se sacrifica. Protégelos.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #1740F5;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Tu acción de 5 minutos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Antes de que termine el mes, toma 5 minutos con cada persona de tu equipo y hazle tres preguntas: ¿Tienes claras tus prioridades? ¿Hay algo que te esté frenando o algo que deberíamos dejar de hacer? ¿Cómo te puedo ayudar?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:20px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;padding:18px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Reconoce a tu equipo</p><p style=\"margin:0 0 14px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">¿Alguien de tu equipo hizo algo extra? Dale un reconocimiento. Toma un minuto y le llegará un correo avisándole.</p><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:10px 18px;\"><a href=\"https://docs.google.com/forms/d/e/1FAIpQLSce5Ey8EsvNqU6S9rSY5aC7DPxCE15Gsf1r5LPE-9iWkOyFGQ/viewform?usp=dialog\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:14px;font-weight:bold;color:#FFFFFF;text-decoration:none;\">Reconocer a alguien &rarr;</a></td></tr></table></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">¿Preguntas o algo con tu equipo que quieras conversar? Escríbele a RR. HH. cuando quieras a <a href=\"mailto:hr@blueprintstudios.com\" style=\"color:#1740F5;font-weight:bold;\">hr@blueprintstudios.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Fuentes: <a href=\"https://www.taylorfrancis.com/chapters/mono/10.4324/9780080549354-5/first-things-first-peter-drucker\" style=\"color:#707070;\">Drucker</a> &middot; <a href=\"https://www.gallup.com/workplace/654911/employee-engagement-sinks-year-low.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_mealperiods.htm\" style=\"color:#707070;\">Cal. DIR: meal periods</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_restperiods.htm\" style=\"color:#707070;\">Cal. DIR: rest periods</a> &middot; <a href=\"https://www.leg.state.nv.us/nrs/nrs-608.html\" style=\"color:#707070;\">Nev. Rev. Stat. 608.019</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Blueprint Studios", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
    on conflict (id) do nothing;
  end if;
  select id into cid from public.clients where lower(name) in ('students run la','srla') limit 1;
  if cid is not null then
    insert into public.newsletters (id, client_id, created_by, data)
    values ('nl-2026-09-srla-manager-minute-en', cid, 'ben@alzapc.com', $nl${"kind": "manager-minute", "month": "2026-09", "lang": "en", "subject": "Manager Minute: Get your team clear for the year-end push", "preview": "One 5-minute conversation that gets everyone clear before the end of the year.", "sendFrom": "Pendolino (ben@pendolinogroup.com)", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Get your team clear for the year-end push</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One 5-minute conversation that gets everyone clear before the end of the year.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#000000\" style=\"background:#000000;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#D9FE52;font-weight:bold;\">Students Run LA<br><span style=\"font-weight:normal;\">September 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#D9FE52;\">This month: Priorities</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Clear the fog before the year-end push</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-left:4px solid #000000;padding:16px 20px;\"><p style=\"margin:0 0 6px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Welcome</p><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">This is the first Manager Minute. Once a month you&#x27;ll get a quick, practical read on one real situation you&#x27;ll probably recognize, the words to use, and one small move to try that week. It&#x27;s short on purpose. Pick one thing and put it to work.</p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">-Ben</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;If there is any one “secret” of effectiveness, it is concentration. Effective executives do first things first and they do one thing at a time.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Peter F. Drucker, The Effective Executive</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Fall is full. New students are starting training, school partners want updates, and year-end fundraising is ramping up. Your program staff are saying yes to everything, and it&#x27;s starting to show.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#000000;\">Why it matters.</b> Gallup found only 46% of U.S. employees clearly know what&#x27;s expected of them at work, down from 56% in 2020. When the calendar fills up, that number doesn&#x27;t fix itself.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;I know everything feels urgent right now. Let&#x27;s take five minutes and get clear on what matters most, and what can wait.&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Everything&#x27;s a priority right now.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#000000;\">Say this:</b> If you only get three things done this month, make it these.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Just figure it out.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#000000;\">Say this:</b> Here&#x27;s what done looks like. What do you need from me to get there?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>We have to do it all.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#000000;\">Say this:</b> This month, students come first. Let&#x27;s pause the extra projects until November.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">In California, nonexempt employees get a 30-minute meal break before the end of their fifth hour of work, plus a paid 10-minute rest break for every four hours. Rest breaks have to be truly off duty. Miss one and the company owes an extra hour of pay for each day it happens. When the calendar fills up, breaks are usually the first thing to slip. Protect them.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #000000;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Before the end of the month, grab 5 minutes with each person on your team and ask three questions: Are you clear on your priorities? Is anything blocking you, or is there something we should stop doing? How can I help?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to Ben anytime at <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#000000;font-weight:bold;\">ben@pendolinogroup.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://www.taylorfrancis.com/chapters/mono/10.4324/9780080549354-5/first-things-first-peter-drucker\" style=\"color:#707070;\">Drucker</a> &middot; <a href=\"https://www.gallup.com/workplace/654911/employee-engagement-sinks-year-low.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_mealperiods.htm\" style=\"color:#707070;\">Cal. DIR: meal periods</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_restperiods.htm\" style=\"color:#707070;\">Cal. DIR: rest periods</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Get your team clear for the year-end push</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One 5-minute conversation that gets everyone clear before the end of the year.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#000000\" style=\"background:#000000;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#D9FE52;font-weight:bold;\">Students Run LA<br><span style=\"font-weight:normal;\">September 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#D9FE52;\">This month: Priorities</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Clear the fog before the year-end push</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-left:4px solid #000000;padding:16px 20px;\"><p style=\"margin:0 0 6px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Welcome</p><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">This is the first Manager Minute. Once a month you&#x27;ll get a quick, practical read on one real situation you&#x27;ll probably recognize, the words to use, and one small move to try that week. It&#x27;s short on purpose. Pick one thing and put it to work.</p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">-Ben</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;If there is any one “secret” of effectiveness, it is concentration. Effective executives do first things first and they do one thing at a time.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Peter F. Drucker, The Effective Executive</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Fall is full. New students are starting training, school partners want updates, and year-end fundraising is ramping up. Your program staff are saying yes to everything, and it&#x27;s starting to show.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#000000;\">Why it matters.</b> Gallup found only 46% of U.S. employees clearly know what&#x27;s expected of them at work, down from 56% in 2020. When the calendar fills up, that number doesn&#x27;t fix itself.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;I know everything feels urgent right now. Let&#x27;s take five minutes and get clear on what matters most, and what can wait.&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Everything&#x27;s a priority right now.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#000000;\">Say this:</b> If you only get three things done this month, make it these.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Just figure it out.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#000000;\">Say this:</b> Here&#x27;s what done looks like. What do you need from me to get there?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>We have to do it all.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#000000;\">Say this:</b> This month, students come first. Let&#x27;s pause the extra projects until November.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">In California, nonexempt employees get a 30-minute meal break before the end of their fifth hour of work, plus a paid 10-minute rest break for every four hours. Rest breaks have to be truly off duty. Miss one and the company owes an extra hour of pay for each day it happens. When the calendar fills up, breaks are usually the first thing to slip. Protect them.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #000000;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Before the end of the month, grab 5 minutes with each person on your team and ask three questions: Are you clear on your priorities? Is anything blocking you, or is there something we should stop doing? How can I help?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to Ben anytime at <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#000000;font-weight:bold;\">ben@pendolinogroup.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://www.taylorfrancis.com/chapters/mono/10.4324/9780080549354-5/first-things-first-peter-drucker\" style=\"color:#707070;\">Drucker</a> &middot; <a href=\"https://www.gallup.com/workplace/654911/employee-engagement-sinks-year-low.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_mealperiods.htm\" style=\"color:#707070;\">Cal. DIR: meal periods</a> &middot; <a href=\"https://www.dir.ca.gov/dlse/faq_restperiods.htm\" style=\"color:#707070;\">Cal. DIR: rest periods</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Students Run LA", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
    on conflict (id) do nothing;
  end if;
  select id into cid from public.clients where lower(name) like '%presidio%' or lower(name) like '%main post%' limit 1;
  if cid is not null then
    insert into public.newsletters (id, client_id, created_by, data)
    values ('nl-2026-10-presidio-intro-en-es', cid, 'ben@alzapc.com', $nl${"kind": "intro", "month": "2026-10", "lang": "en+es", "subject": "Introducing The Pause | Te presentamos La Pausa (English / Español)", "preview": "A few minutes each month, just for you. The first one lands in early October. Versión en español incluida.", "sendFrom": "Pendolino (ben@pendolinogroup.com)", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Introducing The Pause | Te presentamos La Pausa (English / Español)</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">A few minutes each month, just for you. The first one lands in early October. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td height=\"6\" bgcolor=\"#8C2926\" style=\"background:#8C2926;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#8C2926;font-weight:bold;\">Presidio Bay &amp; The Main Post<br><span style=\"color:#707070;font-weight:normal;\">Starts October 2026</span></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#8C2926;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Introducing</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">A monthly time to pause</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">A few minutes each month that are just for you.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Work moves fast. It&#x27;s easy to go weeks without stopping to catch your breath, check in with the people around you, or think about how you&#x27;re actually doing.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">So we&#x27;re starting something new. Once a month you&#x27;ll get The Pause, a short email with one good idea, a couple of small things to try, and a little fun. It takes about three minutes to read, and there&#x27;s nothing you need to reply to.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">What&#x27;s inside</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">One idea backed by real research, something small to try, a way to get moving, a fun fact, and a simple challenge for the month.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">When it lands</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">The first week of every month, right here in your inbox. The first one arrives in early October.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#8C2926\" style=\"background:#8C2926;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#F1D9D8;\">The only ask</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">When it shows up, give it three minutes. Try one thing. That&#x27;s it.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://identity.trinet.com/\" style=\"color:#8C2926;font-weight:bold;\">Log in to TriNet</a> or reach out to Ben at <a href=\"mailto:ben@presidiobay.com\" style=\"color:#8C2926;\">ben@presidiobay.com</a>.<br>Have an idea for a future Pause? Send it to Ben. He&#x27;d love to hear it.</td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #8C2926;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Versión en español</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Te presentamos</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Un momento al mes para hacer una pausa</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Unos minutos cada mes que son solo para ti.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">El trabajo va rápido. Es fácil pasar semanas sin detenerte a respirar, saludar de verdad a quienes te rodean o pensar en cómo estás.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Por eso empezamos algo nuevo. Una vez al mes vas a recibir La Pausa, un correo corto con una buena idea, un par de cosas sencillas para probar y algo divertido. Se lee en unos tres minutos y no tienes que responder nada.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Qué trae</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Una idea respaldada por investigación real, algo pequeño para probar, una forma de moverte, un dato curioso y un reto sencillo para el mes.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Cuándo llega</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">La primera semana de cada mes, aquí en tu correo. La primera llega a principios de octubre.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#8C2926\" style=\"background:#8C2926;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#F1D9D8;\">Lo único que pedimos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Cuando llegue, dale tres minutos. Prueba una cosa. Eso es todo.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">¿Necesitas algo? <a href=\"https://identity.trinet.com/\" style=\"color:#8C2926;font-weight:bold;\">Entra a TriNet</a> o escríbele a Ben a <a href=\"mailto:ben@presidiobay.com\" style=\"color:#8C2926;\">ben@presidiobay.com</a>.<br>¿Tienes una idea para una próxima Pausa? Mándasela a Ben. Le encantaría escucharla.</td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Introducing The Pause | Te presentamos La Pausa (English / Español)</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">A few minutes each month, just for you. The first one lands in early October. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td height=\"6\" bgcolor=\"#8C2926\" style=\"background:#8C2926;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#8C2926;font-weight:bold;\">Presidio Bay &amp; The Main Post<br><span style=\"color:#707070;font-weight:normal;\">Starts October 2026</span></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#8C2926;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Introducing</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">A monthly time to pause</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">A few minutes each month that are just for you.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Work moves fast. It&#x27;s easy to go weeks without stopping to catch your breath, check in with the people around you, or think about how you&#x27;re actually doing.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">So we&#x27;re starting something new. Once a month you&#x27;ll get The Pause, a short email with one good idea, a couple of small things to try, and a little fun. It takes about three minutes to read, and there&#x27;s nothing you need to reply to.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">What&#x27;s inside</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">One idea backed by real research, something small to try, a way to get moving, a fun fact, and a simple challenge for the month.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">When it lands</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">The first week of every month, right here in your inbox. The first one arrives in early October.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#8C2926\" style=\"background:#8C2926;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#F1D9D8;\">The only ask</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">When it shows up, give it three minutes. Try one thing. That&#x27;s it.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://identity.trinet.com/\" style=\"color:#8C2926;font-weight:bold;\">Log in to TriNet</a> or reach out to Ben at <a href=\"mailto:ben@presidiobay.com\" style=\"color:#8C2926;\">ben@presidiobay.com</a>.<br>Have an idea for a future Pause? Send it to Ben. He&#x27;d love to hear it.</td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #8C2926;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Versión en español</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Te presentamos</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Un momento al mes para hacer una pausa</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Unos minutos cada mes que son solo para ti.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">El trabajo va rápido. Es fácil pasar semanas sin detenerte a respirar, saludar de verdad a quienes te rodean o pensar en cómo estás.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Por eso empezamos algo nuevo. Una vez al mes vas a recibir La Pausa, un correo corto con una buena idea, un par de cosas sencillas para probar y algo divertido. Se lee en unos tres minutos y no tienes que responder nada.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Qué trae</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Una idea respaldada por investigación real, algo pequeño para probar, una forma de moverte, un dato curioso y un reto sencillo para el mes.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Cuándo llega</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">La primera semana de cada mes, aquí en tu correo. La primera llega a principios de octubre.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#8C2926\" style=\"background:#8C2926;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#F1D9D8;\">Lo único que pedimos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Cuando llegue, dale tres minutos. Prueba una cosa. Eso es todo.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">¿Necesitas algo? <a href=\"https://identity.trinet.com/\" style=\"color:#8C2926;font-weight:bold;\">Entra a TriNet</a> o escríbele a Ben a <a href=\"mailto:ben@presidiobay.com\" style=\"color:#8C2926;\">ben@presidiobay.com</a>.<br>¿Tienes una idea para una próxima Pausa? Mándasela a Ben. Le encantaría escucharla.</td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Presidio Bay & The Main Post", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
    on conflict (id) do nothing;
  end if;
  select id into cid from public.clients where lower(name) like '%presidio%' or lower(name) like '%main post%' limit 1;
