    values ('nl-2026-10-presidio-the-pause-en-es', cid, 'ben@alzapc.com', $nl${"kind": "the-pause", "month": "2026-10", "lang": "en+es", "subject": "The Pause: The people make the place | La Pausa (English / Español)", "preview": "Two minutes on connection, plus one small thing to try this week. Versión en español incluida.", "sendFrom": "Pendolino (ben@pendolinogroup.com)", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>The Pause: The people make the place | La Pausa</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">Two minutes on connection, plus one small thing to try this week. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tbody><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tbody><tr><td height=\"6\" bgcolor=\"#8C2926\" style=\"background:#8C2926;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#8C2926;font-weight:bold;\">Presidio Bay &amp; The Main Post<br><span style=\"color:#707070;font-weight:normal;\">October 2026</span></td></tr></tbody></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></tbody></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#8C2926;font-weight:bold;text-decoration:none;\">Versión en español abajo ↓</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Introducing&nbsp;</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">The Pause&nbsp;</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\"><span style=\"color: rgb(43, 43, 43); font-family: Arial, Helvetica, sans-serif; font-size: 17px; font-style: normal;\">Work moves fast. It's easy to go weeks without stopping to catch your breath, check in with the people around you, or think about how you're actually doing. This email is meant to help you pause, think and be your best self.&nbsp;</span></p></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">This month: Connection</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">The people make the place</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Small moments with the people around you add up.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard has been studying what makes people happy since 1938, following the same group for more than 80 years. The answer wasn't money or success. It was good relationships. And they don't have to be deep ones. A laugh before the Monday meeting, a real “how was your weekend,” or lunch with someone from another team all count.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Try this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Ask a coworker one question this week that isn't about work. \"What's keeping you busy outside of here?\" works. Then actually listen to the answer.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Get moving</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Take a 10-minute walk around the block or a coffee run with someone. Heading out to a site? Bring a teammate along. A Stanford study found walking boosted creative ideas by about 60%.</p></td></tr></tbody></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Worth knowing</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8C2926;\">Fun fact</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">People laugh about 30 times more often with others than when they're alone, according to laughter researcher Robert Provine. Good company is contagious.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8C2926;\">Oct 10</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">World Mental Health Day. A good excuse to check in on someone, including yourself.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8C2926;\">Nov 1</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Clocks fall back an hour. Enjoy the extra sleep.</td></tr></tbody></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#8C2926\" style=\"background:#8C2926;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#F1D9D8;\">Your challenge</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Connect with 3 people this month you don't usually talk to. Someone on another team, someone new, someone you mostly know from email threads. A quick hello counts.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://identity.trinet.com/\" style=\"color:#8C2926;font-weight:bold;\">Log in to TriNet</a> or reach out to Ben at <a href=\"mailto:ben@presidiobay.com\" style=\"color:#8C2926;\">ben@presidiobay.com</a>.<br>Carrying something heavier? Reach out to Ben anytime. Happy to help.<br><br><span style=\"font-size:11px;\">Sources: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> · <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> · <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> · <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td style=\"border-top:6px solid #8C2926;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Versión en español</p></td></tr></tbody></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Este mes: Conexión</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Las personas hacen el lugar</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Los pequeños momentos con quienes te rodean suman.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard lleva desde 1938 estudiando qué hace feliz a la gente, siguiendo al mismo grupo por más de 80 años. La respuesta no fue el dinero ni el éxito. Fueron las buenas relaciones. Y no tienen que ser profundas. Una risa antes de la junta del lunes, un “¿qué tal tu fin de semana?” sincero o un almuerzo con alguien de otro equipo cuentan.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Prueba esto</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Esta semana, hazle a un compañero una pregunta que no sea de trabajo. \"¿Qué te tiene ocupado fuera de aquí?\" funciona. Luego escucha de verdad la respuesta.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Muévete</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Sal a caminar 10 minutos alrededor de la cuadra o por un café con alguien. ¿Vas a visitar un proyecto? Lleva a un compañero. Un estudio de Stanford encontró que caminar aumentó las ideas creativas en cerca de un 60%.</p></td></tr></tbody></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Bueno saber</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8C2926;\">Dato curioso</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Según el investigador Robert Provine, las personas se ríen unas 30 veces más cuando están con otros que cuando están solas. La buena compañía se contagia.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8C2926;\">10 oct</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Día Mundial de la Salud Mental. Un buen pretexto para preguntarle a alguien cómo está, incluyéndote a ti.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8C2926;\">1 nov</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Se atrasan los relojes una hora. Disfruta el sueño extra.</td></tr></tbody></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#8C2926\" style=\"background:#8C2926;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#F1D9D8;\">Tu reto</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Conecta este mes con 3 personas con las que normalmente no hablas: alguien de otro equipo, alguien nuevo, alguien que conoces sobre todo por correo. Un simple saludo cuenta.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">¿Necesitas algo? <a href=\"https://identity.trinet.com/\" style=\"color:#8C2926;font-weight:bold;\">Entra a TriNet</a> o escríbele a Ben a <a href=\"mailto:ben@presidiobay.com\" style=\"color:#8C2926;\">ben@presidiobay.com</a>.<br>¿Cargas con algo más pesado? Escríbele a Ben cuando quieras. Con gusto te ayuda.<br><br><span style=\"font-size:11px;\">Fuentes: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> · <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> · <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> · <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a></span></td></tr><!--/BODY-->\n</tbody></table></td></tr></tbody></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>The Pause: The people make the place | La Pausa</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">Two minutes on connection, plus one small thing to try this week. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td height=\"6\" bgcolor=\"#8C2926\" style=\"background:#8C2926;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#8C2926;font-weight:bold;\">Presidio Bay &amp; The Main Post<br><span style=\"color:#707070;font-weight:normal;\">October 2026</span></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#8C2926;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">This month: Connection</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">The people make the place</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Small moments with the people around you add up.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard has been studying what makes people happy since 1938, following the same group for more than 80 years. The answer wasn&#x27;t money or success. It was good relationships. And they don&#x27;t have to be deep ones. A laugh before the Monday meeting, a real “how was your weekend,” or lunch with someone from another team all count.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Try this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Ask a coworker one question this week that isn&#x27;t about work. &quot;What&#x27;s keeping you busy outside of here?&quot; works. Then actually listen to the answer.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Get moving</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Take a 10-minute walk around the block or a coffee run with someone. Heading out to a site? Bring a teammate along. A Stanford study found walking boosted creative ideas by about 60%.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Worth knowing</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8C2926;\">Fun fact</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">People laugh about 30 times more often with others than when they&#x27;re alone, according to laughter researcher Robert Provine. Good company is contagious.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8C2926;\">Oct 10</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">World Mental Health Day. A good excuse to check in on someone, including yourself.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8C2926;\">Nov 1</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Clocks fall back an hour. Enjoy the extra sleep.</td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#8C2926\" style=\"background:#8C2926;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#F1D9D8;\">Your challenge</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Connect with 3 people this month you don&#x27;t usually talk to. Someone on another team, someone new, someone you mostly know from email threads. A quick hello counts.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://identity.trinet.com/\" style=\"color:#8C2926;font-weight:bold;\">Log in to TriNet</a> or reach out to Ben at <a href=\"mailto:ben@presidiobay.com\" style=\"color:#8C2926;\">ben@presidiobay.com</a>.<br>Carrying something heavier? Reach out to Ben anytime. Happy to help.<br><br><span style=\"font-size:11px;\">Sources: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> &middot; <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> &middot; <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> &middot; <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #8C2926;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Versión en español</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Este mes: Conexión</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Las personas hacen el lugar</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Los pequeños momentos con quienes te rodean suman.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard lleva desde 1938 estudiando qué hace feliz a la gente, siguiendo al mismo grupo por más de 80 años. La respuesta no fue el dinero ni el éxito. Fueron las buenas relaciones. Y no tienen que ser profundas. Una risa antes de la junta del lunes, un “¿qué tal tu fin de semana?” sincero o un almuerzo con alguien de otro equipo cuentan.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Prueba esto</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Esta semana, hazle a un compañero una pregunta que no sea de trabajo. &quot;¿Qué te tiene ocupado fuera de aquí?&quot; funciona. Luego escucha de verdad la respuesta.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Muévete</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Sal a caminar 10 minutos alrededor de la cuadra o por un café con alguien. ¿Vas a visitar un proyecto? Lleva a un compañero. Un estudio de Stanford encontró que caminar aumentó las ideas creativas en cerca de un 60%.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Bueno saber</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8C2926;\">Dato curioso</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Según el investigador Robert Provine, las personas se ríen unas 30 veces más cuando están con otros que cuando están solas. La buena compañía se contagia.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8C2926;\">10 oct</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Día Mundial de la Salud Mental. Un buen pretexto para preguntarle a alguien cómo está, incluyéndote a ti.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8C2926;\">1 nov</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Se atrasan los relojes una hora. Disfruta el sueño extra.</td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#8C2926\" style=\"background:#8C2926;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#F1D9D8;\">Tu reto</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Conecta este mes con 3 personas con las que normalmente no hablas: alguien de otro equipo, alguien nuevo, alguien que conoces sobre todo por correo. Un simple saludo cuenta.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">¿Necesitas algo? <a href=\"https://identity.trinet.com/\" style=\"color:#8C2926;font-weight:bold;\">Entra a TriNet</a> o escríbele a Ben a <a href=\"mailto:ben@presidiobay.com\" style=\"color:#8C2926;\">ben@presidiobay.com</a>.<br>¿Cargas con algo más pesado? Escríbele a Ben cuando quieras. Con gusto te ayuda.<br><br><span style=\"font-size:11px;\">Fuentes: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> &middot; <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> &middot; <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> &middot; <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Presidio Bay & The Main Post", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
    on conflict (id) do nothing;
  end if;
  select id into cid from public.clients where lower(name) like '%presidio%' or lower(name) like '%main post%' limit 1;
  if cid is not null then
    insert into public.newsletters (id, client_id, created_by, data)
    values ('nl-2026-10-presidio-manager-minute-en', cid, 'ben@alzapc.com', $nl${"kind": "manager-minute", "month": "2026-10", "lang": "en", "subject": "Manager Minute: Feedback that actually lands", "preview": "One script, one swap, and a 5-minute move for this week.", "sendFrom": "Pendolino (ben@pendolinogroup.com)", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Feedback that actually lands</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One script, one swap, and a 5-minute move for this week.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#8C2926\" style=\"background:#8C2926;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#F1D9D8;font-weight:bold;\">Presidio Bay &amp; The Main Post<br><span style=\"font-weight:normal;\">October 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#F1D9D8;\">This month: Feedback</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Feedback that actually lands</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Clear is kind. Unclear is unkind.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Brené Brown, Dare to Lead</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Someone on your team put together a strong investment memo last week. But the rent roll didn&#x27;t tie to the model, and the deal team spent about an hour reconciling it right before the call. You&#x27;ve been meaning to say something. It&#x27;s been five days.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#8C2926;\">Why it matters.</b> Gallup found that 80% of employees who got meaningful feedback in the past week are fully engaged. Timing is half the battle.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;Got two minutes? The memo was sharp, and the partners noticed. One thing: the rent roll didn&#x27;t tie to the model, and the team spent about an hour reconciling it before the call. Next time, can you run a quick tie-out before it goes around? What would make that easier?&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Good job.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8C2926;\">Say this:</b> Your market comps really made the case in that investment committee meeting.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>You need to be more careful.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8C2926;\">Say this:</b> The rent roll didn&#x27;t tie to the model. Can you run a tie-out before it goes around next time?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Why is this late again?</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8C2926;\">Say this:</b> What got in the way, and what do you need from me?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">In California, current and former employees can ask to see their personnel file, and the company has 30 days to produce it (Labor Code 1198.5). Anything you write about someone&#x27;s performance may end up in front of them. Write it like they&#x27;ll read it: specific, factual, about the work, never the person.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #8C2926;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Pick one person on your team. Before Friday, give them one specific piece of feedback, positive or corrective, within a day of the moment. Keep it under two minutes.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to Ben anytime at <a href=\"mailto:ben@presidiobay.com\" style=\"color:#8C2926;font-weight:bold;\">ben@presidiobay.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://brenebrown.com/articles/2018/10/15/clear-is-kind-unclear-is-unkind/\" style=\"color:#707070;\">Brené Brown</a> &middot; <a href=\"https://www.gallup.com/workplace/357764/fast-feedback-fuels-performance.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://law.justia.com/codes/california/code-lab/division-2/part-4/chapter-1/section-1198-5/\" style=\"color:#707070;\">Cal. Labor Code 1198.5</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Feedback that actually lands</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One script, one swap, and a 5-minute move for this week.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#8C2926\" style=\"background:#8C2926;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#F1D9D8;font-weight:bold;\">Presidio Bay &amp; The Main Post<br><span style=\"font-weight:normal;\">October 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#F1D9D8;\">This month: Feedback</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Feedback that actually lands</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Clear is kind. Unclear is unkind.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Brené Brown, Dare to Lead</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Someone on your team put together a strong investment memo last week. But the rent roll didn&#x27;t tie to the model, and the deal team spent about an hour reconciling it right before the call. You&#x27;ve been meaning to say something. It&#x27;s been five days.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#8C2926;\">Why it matters.</b> Gallup found that 80% of employees who got meaningful feedback in the past week are fully engaged. Timing is half the battle.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;Got two minutes? The memo was sharp, and the partners noticed. One thing: the rent roll didn&#x27;t tie to the model, and the team spent about an hour reconciling it before the call. Next time, can you run a quick tie-out before it goes around? What would make that easier?&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Good job.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8C2926;\">Say this:</b> Your market comps really made the case in that investment committee meeting.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>You need to be more careful.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8C2926;\">Say this:</b> The rent roll didn&#x27;t tie to the model. Can you run a tie-out before it goes around next time?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Why is this late again?</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8C2926;\">Say this:</b> What got in the way, and what do you need from me?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F5EEEE\" style=\"background:#F5EEEE;border-top:3px solid #8C2926;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">In California, current and former employees can ask to see their personnel file, and the company has 30 days to produce it (Labor Code 1198.5). Anything you write about someone&#x27;s performance may end up in front of them. Write it like they&#x27;ll read it: specific, factual, about the work, never the person.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #8C2926;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C2926;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Pick one person on your team. Before Friday, give them one specific piece of feedback, positive or corrective, within a day of the moment. Keep it under two minutes.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to Ben anytime at <a href=\"mailto:ben@presidiobay.com\" style=\"color:#8C2926;font-weight:bold;\">ben@presidiobay.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://brenebrown.com/articles/2018/10/15/clear-is-kind-unclear-is-unkind/\" style=\"color:#707070;\">Brené Brown</a> &middot; <a href=\"https://www.gallup.com/workplace/357764/fast-feedback-fuels-performance.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://law.justia.com/codes/california/code-lab/division-2/part-4/chapter-1/section-1198-5/\" style=\"color:#707070;\">Cal. Labor Code 1198.5</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Presidio Bay & The Main Post", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
    on conflict (id) do nothing;
  end if;
  select id into cid from public.clients where lower(name) like 'hensley%' limit 1;
  if cid is not null then
    insert into public.newsletters (id, client_id, created_by, data)
    values ('nl-2026-10-hensley-intro-en-es', cid, 'ben@alzapc.com', $nl${"kind": "intro", "month": "2026-10", "lang": "en+es", "subject": "Introducing The Pause | Te presentamos La Pausa (English / Español)", "preview": "A few minutes each month, just for you. The first one lands in early October. Versión en español incluida.", "sendFrom": "hr@blueprintstudios.com", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Introducing The Pause | Te presentamos La Pausa (English / Español)</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">A few minutes each month, just for you. The first one lands in early October. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td height=\"6\" bgcolor=\"#231F20\" style=\"background:#231F20;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#8F6A1C;font-weight:bold;\">Hensley Event Resources<br><span style=\"color:#707070;font-weight:normal;\">Starts October 2026</span></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#8F6A1C;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Introducing</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">A monthly time to pause</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">A few minutes each month that are just for you.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Work moves fast. It&#x27;s easy to go weeks without stopping to catch your breath, check in with the people around you, or think about how you&#x27;re actually doing.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">So we&#x27;re starting something new. Once a month you&#x27;ll get The Pause, a short email with one good idea, a couple of small things to try, and a little fun. It takes about three minutes to read, and there&#x27;s nothing you need to reply to.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">What&#x27;s inside</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">One idea backed by real research, something small to try, a way to get moving, a fun fact, and a simple challenge for the month.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">When it lands</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">The first week of every month, right here in your inbox. The first one arrives in early October.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#231F20\" style=\"background:#231F20;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C3922F;\">The only ask</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">When it shows up, give it three minutes. Try one thing. That&#x27;s it.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://my.adp.com\" style=\"color:#8F6A1C;font-weight:bold;\">Log in to ADP</a> or email <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#8F6A1C;\">HR@blueprintstudios.com</a>.<br>Have an idea for a future Pause? We&#x27;d love to hear it.</td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #231F20;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Versión en español</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Te presentamos</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Un momento al mes para hacer una pausa</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Unos minutos cada mes que son solo para ti.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">El trabajo va rápido. Es fácil pasar semanas sin detenerte a respirar, saludar de verdad a quienes te rodean o pensar en cómo estás.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Por eso empezamos algo nuevo. Una vez al mes vas a recibir La Pausa, un correo corto con una buena idea, un par de cosas sencillas para probar y algo divertido. Se lee en unos tres minutos y no tienes que responder nada.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Qué trae</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Una idea respaldada por investigación real, algo pequeño para probar, una forma de moverte, un dato curioso y un reto sencillo para el mes.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Cuándo llega</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">La primera semana de cada mes, aquí en tu correo. La primera llega a principios de octubre.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#231F20\" style=\"background:#231F20;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C3922F;\">Lo único que pedimos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Cuando llegue, dale tres minutos. Prueba una cosa. Eso es todo.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">¿Necesitas algo? <a href=\"https://my.adp.com\" style=\"color:#8F6A1C;font-weight:bold;\">Entra a ADP</a> o escribe a <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#8F6A1C;\">HR@blueprintstudios.com</a>.<br>¿Tienes una idea para una próxima Pausa? Nos encantaría escucharla.</td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Introducing The Pause | Te presentamos La Pausa (English / Español)</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">A few minutes each month, just for you. The first one lands in early October. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td height=\"6\" bgcolor=\"#231F20\" style=\"background:#231F20;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#8F6A1C;font-weight:bold;\">Hensley Event Resources<br><span style=\"color:#707070;font-weight:normal;\">Starts October 2026</span></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#8F6A1C;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Introducing</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">A monthly time to pause</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">A few minutes each month that are just for you.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Work moves fast. It&#x27;s easy to go weeks without stopping to catch your breath, check in with the people around you, or think about how you&#x27;re actually doing.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">So we&#x27;re starting something new. Once a month you&#x27;ll get The Pause, a short email with one good idea, a couple of small things to try, and a little fun. It takes about three minutes to read, and there&#x27;s nothing you need to reply to.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">What&#x27;s inside</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">One idea backed by real research, something small to try, a way to get moving, a fun fact, and a simple challenge for the month.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">When it lands</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">The first week of every month, right here in your inbox. The first one arrives in early October.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#231F20\" style=\"background:#231F20;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C3922F;\">The only ask</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">When it shows up, give it three minutes. Try one thing. That&#x27;s it.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://my.adp.com\" style=\"color:#8F6A1C;font-weight:bold;\">Log in to ADP</a> or email <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#8F6A1C;\">HR@blueprintstudios.com</a>.<br>Have an idea for a future Pause? We&#x27;d love to hear it.</td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #231F20;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Versión en español</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Te presentamos</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Un momento al mes para hacer una pausa</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Unos minutos cada mes que son solo para ti.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">El trabajo va rápido. Es fácil pasar semanas sin detenerte a respirar, saludar de verdad a quienes te rodean o pensar en cómo estás.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Por eso empezamos algo nuevo. Una vez al mes vas a recibir La Pausa, un correo corto con una buena idea, un par de cosas sencillas para probar y algo divertido. Se lee en unos tres minutos y no tienes que responder nada.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Qué trae</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Una idea respaldada por investigación real, algo pequeño para probar, una forma de moverte, un dato curioso y un reto sencillo para el mes.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Cuándo llega</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">La primera semana de cada mes, aquí en tu correo. La primera llega a principios de octubre.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#231F20\" style=\"background:#231F20;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C3922F;\">Lo único que pedimos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Cuando llegue, dale tres minutos. Prueba una cosa. Eso es todo.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">¿Necesitas algo? <a href=\"https://my.adp.com\" style=\"color:#8F6A1C;font-weight:bold;\">Entra a ADP</a> o escribe a <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#8F6A1C;\">HR@blueprintstudios.com</a>.<br>¿Tienes una idea para una próxima Pausa? Nos encantaría escucharla.</td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Hensley Event Resources", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
