    values ('nl-2026-10-hensley-the-pause-en-es', cid, 'ben@alzapc.com', $nl${"kind": "the-pause", "month": "2026-10", "lang": "en+es", "subject": "The Pause: The people make the place | La Pausa (English / Español)", "preview": "Two minutes on connection, plus one small thing to try this week. Versión en español incluida.", "sendFrom": "hr@blueprintstudios.com", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>The Pause: The people make the place | La Pausa</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">Two minutes on connection, plus one small thing to try this week. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td height=\"6\" bgcolor=\"#231F20\" style=\"background:#231F20;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#8F6A1C;font-weight:bold;\">Hensley Event Resources<br><span style=\"color:#707070;font-weight:normal;\">October 2026</span></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#8F6A1C;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">This month: Connection</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">The people make the place</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Small moments with the people around you add up.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard has been studying what makes people happy since 1938, following the same group for more than 80 years. The answer wasn&#x27;t money or success. It was good relationships. And they don&#x27;t have to be deep ones. A laugh during load-in, a real “how was your weekend,” or lunch with someone from the other side of the building all count.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Try this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Ask a coworker one question this week that isn&#x27;t about work. &quot;What&#x27;s keeping you busy outside of here?&quot; works. Then actually listen to the answer.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Get moving</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Take a 10-minute walk or a coffee run with someone from the office. On the warehouse floor or out on an install? Take your next break with someone from the crew. A Stanford study found walking boosted creative ideas by about 60%.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Worth knowing</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8F6A1C;\">Fun fact</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">People laugh about 30 times more often with others than when they&#x27;re alone, according to laughter researcher Robert Provine. Good company is contagious.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8F6A1C;\">Oct 10</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">World Mental Health Day. A good excuse to check in on someone, including yourself.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8F6A1C;\">Nov 1</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Clocks fall back an hour. Enjoy the extra sleep.</td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#231F20\" style=\"background:#231F20;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C3922F;\">Your challenge</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Connect with 3 people this month you don&#x27;t usually talk to. In the office? Go say hi to someone in the warehouse. On the crew? Stop by the office. A quick hello counts.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://my.adp.com\" style=\"color:#8F6A1C;font-weight:bold;\">Log in to ADP</a> or email <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#8F6A1C;\">HR@blueprintstudios.com</a>.<br>Carrying something heavier? Reach out to HR. We&#x27;re here to help.<br><br><span style=\"font-size:11px;\">Sources: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> &middot; <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> &middot; <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> &middot; <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #231F20;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Versión en español</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Este mes: Conexión</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Las personas hacen el lugar</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Los pequeños momentos con quienes te rodean suman.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard lleva desde 1938 estudiando qué hace feliz a la gente, siguiendo al mismo grupo por más de 80 años. La respuesta no fue el dinero ni el éxito. Fueron las buenas relaciones. Y no tienen que ser profundas. Una risa durante el montaje, un “¿qué tal tu fin de semana?” sincero o un almuerzo con alguien del otro lado del edificio cuentan.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Prueba esto</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Esta semana, hazle a un compañero una pregunta que no sea de trabajo. &quot;¿Qué te tiene ocupado fuera de aquí?&quot; funciona. Luego escucha de verdad la respuesta.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Muévete</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Sal a caminar 10 minutos o por un café con alguien de la oficina. ¿En el almacén o en una instalación? Toma tu próximo descanso con alguien de la cuadrilla. Un estudio de Stanford encontró que caminar aumentó las ideas creativas en cerca de un 60%.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Bueno saber</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8F6A1C;\">Dato curioso</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Según el investigador Robert Provine, las personas se ríen unas 30 veces más cuando están con otros que cuando están solas. La buena compañía se contagia.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8F6A1C;\">10 oct</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Día Mundial de la Salud Mental. Un buen pretexto para preguntarle a alguien cómo está, incluyéndote a ti.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8F6A1C;\">1 nov</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Se atrasan los relojes una hora. Disfruta el sueño extra.</td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#231F20\" style=\"background:#231F20;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C3922F;\">Tu reto</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Conecta este mes con 3 personas con las que normalmente no hablas. ¿Estás en la oficina? Ve a saludar a alguien del almacén. ¿Estás en la cuadrilla? Pasa por la oficina. Un simple saludo cuenta.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">¿Necesitas algo? <a href=\"https://my.adp.com\" style=\"color:#8F6A1C;font-weight:bold;\">Entra a ADP</a> o escribe a <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#8F6A1C;\">HR@blueprintstudios.com</a>.<br>¿Cargas con algo más pesado? Escríbenos. Estamos para ayudarte.<br><br><span style=\"font-size:11px;\">Fuentes: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> &middot; <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> &middot; <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> &middot; <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>The Pause: The people make the place | La Pausa</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">Two minutes on connection, plus one small thing to try this week. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td height=\"6\" bgcolor=\"#231F20\" style=\"background:#231F20;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#8F6A1C;font-weight:bold;\">Hensley Event Resources<br><span style=\"color:#707070;font-weight:normal;\">October 2026</span></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#8F6A1C;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">This month: Connection</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">The people make the place</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Small moments with the people around you add up.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard has been studying what makes people happy since 1938, following the same group for more than 80 years. The answer wasn&#x27;t money or success. It was good relationships. And they don&#x27;t have to be deep ones. A laugh during load-in, a real “how was your weekend,” or lunch with someone from the other side of the building all count.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Try this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Ask a coworker one question this week that isn&#x27;t about work. &quot;What&#x27;s keeping you busy outside of here?&quot; works. Then actually listen to the answer.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Get moving</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Take a 10-minute walk or a coffee run with someone from the office. On the warehouse floor or out on an install? Take your next break with someone from the crew. A Stanford study found walking boosted creative ideas by about 60%.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Worth knowing</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8F6A1C;\">Fun fact</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">People laugh about 30 times more often with others than when they&#x27;re alone, according to laughter researcher Robert Provine. Good company is contagious.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8F6A1C;\">Oct 10</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">World Mental Health Day. A good excuse to check in on someone, including yourself.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8F6A1C;\">Nov 1</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Clocks fall back an hour. Enjoy the extra sleep.</td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#231F20\" style=\"background:#231F20;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C3922F;\">Your challenge</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Connect with 3 people this month you don&#x27;t usually talk to. In the office? Go say hi to someone in the warehouse. On the crew? Stop by the office. A quick hello counts.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://my.adp.com\" style=\"color:#8F6A1C;font-weight:bold;\">Log in to ADP</a> or email <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#8F6A1C;\">HR@blueprintstudios.com</a>.<br>Carrying something heavier? Reach out to HR. We&#x27;re here to help.<br><br><span style=\"font-size:11px;\">Sources: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> &middot; <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> &middot; <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> &middot; <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #231F20;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Versión en español</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Este mes: Conexión</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Las personas hacen el lugar</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Los pequeños momentos con quienes te rodean suman.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard lleva desde 1938 estudiando qué hace feliz a la gente, siguiendo al mismo grupo por más de 80 años. La respuesta no fue el dinero ni el éxito. Fueron las buenas relaciones. Y no tienen que ser profundas. Una risa durante el montaje, un “¿qué tal tu fin de semana?” sincero o un almuerzo con alguien del otro lado del edificio cuentan.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Prueba esto</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Esta semana, hazle a un compañero una pregunta que no sea de trabajo. &quot;¿Qué te tiene ocupado fuera de aquí?&quot; funciona. Luego escucha de verdad la respuesta.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Muévete</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Sal a caminar 10 minutos o por un café con alguien de la oficina. ¿En el almacén o en una instalación? Toma tu próximo descanso con alguien de la cuadrilla. Un estudio de Stanford encontró que caminar aumentó las ideas creativas en cerca de un 60%.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Bueno saber</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8F6A1C;\">Dato curioso</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Según el investigador Robert Provine, las personas se ríen unas 30 veces más cuando están con otros que cuando están solas. La buena compañía se contagia.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8F6A1C;\">10 oct</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Día Mundial de la Salud Mental. Un buen pretexto para preguntarle a alguien cómo está, incluyéndote a ti.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#8F6A1C;\">1 nov</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Se atrasan los relojes una hora. Disfruta el sueño extra.</td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#231F20\" style=\"background:#231F20;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C3922F;\">Tu reto</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Conecta este mes con 3 personas con las que normalmente no hablas. ¿Estás en la oficina? Ve a saludar a alguien del almacén. ¿Estás en la cuadrilla? Pasa por la oficina. Un simple saludo cuenta.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">¿Necesitas algo? <a href=\"https://my.adp.com\" style=\"color:#8F6A1C;font-weight:bold;\">Entra a ADP</a> o escribe a <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#8F6A1C;\">HR@blueprintstudios.com</a>.<br>¿Cargas con algo más pesado? Escríbenos. Estamos para ayudarte.<br><br><span style=\"font-size:11px;\">Fuentes: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> &middot; <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> &middot; <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> &middot; <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Hensley Event Resources", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
    on conflict (id) do nothing;
  end if;
  select id into cid from public.clients where lower(name) like 'hensley%' limit 1;
  if cid is not null then
    insert into public.newsletters (id, client_id, created_by, data)
    values ('nl-2026-10-hensley-manager-minute-en-es', cid, 'ben@alzapc.com', $nl${"kind": "manager-minute", "month": "2026-10", "lang": "en+es", "subject": "Manager Minute: Feedback that actually lands | Minuto del Líder (English / Español)", "preview": "One script, one swap, and a 5-minute move for this week. Versión en español incluida.", "sendFrom": "hr@blueprintstudios.com", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Feedback that actually lands | Minuto del Líder</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One script, one swap, and a 5-minute move for this week. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#231F20\" style=\"background:#231F20;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#C3922F;font-weight:bold;\">Hensley Event Resources<br><span style=\"font-weight:normal;\">October 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C3922F;\">This month: Feedback</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Feedback that actually lands</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#8F6A1C;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Clear is kind. Unclear is unkind.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Brené Brown, Dare to Lead</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Your install lead did great work on a big event last weekend. But the load-out sheet didn&#x27;t match what went on the truck, and the crew lost about an hour tracking down missing pieces. You&#x27;ve been meaning to say something. It&#x27;s been five days.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#8F6A1C;\">Why it matters.</b> Gallup found that 80% of employees who got meaningful feedback in the past week are fully engaged. Timing is half the battle.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;Got two minutes? That install looked great, and the client noticed. One thing: the load-out sheet didn&#x27;t match the truck, and the crew spent about an hour hunting for pieces. Next time, can you double-check the sheet before the truck leaves? What would make that easier?&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Good job.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Say this:</b> The way you handled that client walkthrough kept the whole event on schedule.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>You need to be more careful.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Say this:</b> The load-out sheet didn&#x27;t match the truck. Can you check it before it leaves next time?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Why is this late again?</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Say this:</b> What got in the way, and what do you need from me?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">In California, current and former employees can ask to see their personnel file, and the company has 30 days to produce it (Labor Code 1198.5). Anything you write about someone&#x27;s performance may end up in front of them. Write it like they&#x27;ll read it: specific, factual, about the work, never the person.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #C3922F;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Pick one person on your team, in the office or on the crew. Before Friday, give them one specific piece of feedback, positive or corrective, within a day of the moment. Keep it under two minutes.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to Ben anytime at <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#8F6A1C;font-weight:bold;\">ben@pendolinogroup.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://brenebrown.com/articles/2018/10/15/clear-is-kind-unclear-is-unkind/\" style=\"color:#707070;\">Brené Brown</a> &middot; <a href=\"https://www.gallup.com/workplace/357764/fast-feedback-fuels-performance.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://law.justia.com/codes/california/code-lab/division-2/part-4/chapter-1/section-1198-5/\" style=\"color:#707070;\">Cal. Labor Code 1198.5</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #231F20;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Versión en español</p><h2 style=\"margin:6px 0 0 0;font-family:Georgia, 'Times New Roman', serif;font-size:28px;font-weight:normal;line-height:1.2;color:#2B2B2B;\">Minuto del Líder: Retroalimentación que sí llega</h2></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Ser claro es ser amable. No serlo, no lo es.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Brené Brown, Dare to Lead (traducción)</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Tu líder de instalación hizo un gran trabajo en un evento grande el fin de semana pasado. Pero la hoja de carga no coincidía con lo que subió al camión, y la cuadrilla perdió cerca de una hora buscando piezas. Has querido decir algo. Ya pasaron cinco días.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#8F6A1C;\">Por qué importa.</b> Gallup encontró que el 80% de los empleados que recibieron retroalimentación significativa en la última semana están plenamente comprometidos. El momento lo es todo.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Qué decir</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;¿Tienes dos minutos? Esa instalación quedó muy bien y el cliente lo notó. Una cosa: la hoja de carga no coincidía con el camión, y la cuadrilla pasó cerca de una hora buscando piezas. La próxima vez, ¿puedes revisar la hoja antes de que salga el camión? ¿Qué te lo haría más fácil?&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Líder vs. jefe</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Buen trabajo.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Di esto:</b> La forma en que manejaste el recorrido con el cliente mantuvo todo el evento a tiempo.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Tienes que tener más cuidado.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Di esto:</b> La hoja de carga no coincidía con el camión. ¿Puedes revisarla antes de que salga la próxima vez?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>¿Por qué se atrasó otra vez?</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Di esto:</b> ¿Qué se interpuso y qué necesitas de mí?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Lo que debes saber</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">En California, los empleados actuales y anteriores pueden pedir ver su expediente de personal, y la empresa tiene 30 días para entregarlo (Código Laboral 1198.5). Todo lo que escribas sobre el desempeño de alguien puede terminar en sus manos. Escríbelo como si lo fuera a leer: específico, basado en hechos, sobre el trabajo y nunca sobre la persona.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #C3922F;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Tu acción de 5 minutos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Elige a una persona de tu equipo, en la oficina o en la cuadrilla. Antes del viernes, dale una retroalimentación específica, positiva o de mejora, dentro de un día del momento. Que dure menos de dos minutos.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">¿Preguntas o algo con tu equipo que quieras conversar? Escríbele a Ben cuando quieras a <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#8F6A1C;font-weight:bold;\">ben@pendolinogroup.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Fuentes: <a href=\"https://brenebrown.com/articles/2018/10/15/clear-is-kind-unclear-is-unkind/\" style=\"color:#707070;\">Brené Brown</a> &middot; <a href=\"https://www.gallup.com/workplace/357764/fast-feedback-fuels-performance.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://law.justia.com/codes/california/code-lab/division-2/part-4/chapter-1/section-1198-5/\" style=\"color:#707070;\">Código Laboral de Cal. 1198.5</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Feedback that actually lands | Minuto del Líder</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One script, one swap, and a 5-minute move for this week. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#231F20\" style=\"background:#231F20;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#C3922F;font-weight:bold;\">Hensley Event Resources<br><span style=\"font-weight:normal;\">October 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C3922F;\">This month: Feedback</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Feedback that actually lands</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#8F6A1C;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Clear is kind. Unclear is unkind.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Brené Brown, Dare to Lead</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Your install lead did great work on a big event last weekend. But the load-out sheet didn&#x27;t match what went on the truck, and the crew lost about an hour tracking down missing pieces. You&#x27;ve been meaning to say something. It&#x27;s been five days.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#8F6A1C;\">Why it matters.</b> Gallup found that 80% of employees who got meaningful feedback in the past week are fully engaged. Timing is half the battle.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;Got two minutes? That install looked great, and the client noticed. One thing: the load-out sheet didn&#x27;t match the truck, and the crew spent about an hour hunting for pieces. Next time, can you double-check the sheet before the truck leaves? What would make that easier?&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Good job.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Say this:</b> The way you handled that client walkthrough kept the whole event on schedule.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>You need to be more careful.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Say this:</b> The load-out sheet didn&#x27;t match the truck. Can you check it before it leaves next time?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Why is this late again?</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Say this:</b> What got in the way, and what do you need from me?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">In California, current and former employees can ask to see their personnel file, and the company has 30 days to produce it (Labor Code 1198.5). Anything you write about someone&#x27;s performance may end up in front of them. Write it like they&#x27;ll read it: specific, factual, about the work, never the person.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #C3922F;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Pick one person on your team, in the office or on the crew. Before Friday, give them one specific piece of feedback, positive or corrective, within a day of the moment. Keep it under two minutes.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to Ben anytime at <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#8F6A1C;font-weight:bold;\">ben@pendolinogroup.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://brenebrown.com/articles/2018/10/15/clear-is-kind-unclear-is-unkind/\" style=\"color:#707070;\">Brené Brown</a> &middot; <a href=\"https://www.gallup.com/workplace/357764/fast-feedback-fuels-performance.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://law.justia.com/codes/california/code-lab/division-2/part-4/chapter-1/section-1198-5/\" style=\"color:#707070;\">Cal. Labor Code 1198.5</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #231F20;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Versión en español</p><h2 style=\"margin:6px 0 0 0;font-family:Georgia, 'Times New Roman', serif;font-size:28px;font-weight:normal;line-height:1.2;color:#2B2B2B;\">Minuto del Líder: Retroalimentación que sí llega</h2></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Ser claro es ser amable. No serlo, no lo es.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Brené Brown, Dare to Lead (traducción)</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Tu líder de instalación hizo un gran trabajo en un evento grande el fin de semana pasado. Pero la hoja de carga no coincidía con lo que subió al camión, y la cuadrilla perdió cerca de una hora buscando piezas. Has querido decir algo. Ya pasaron cinco días.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#8F6A1C;\">Por qué importa.</b> Gallup encontró que el 80% de los empleados que recibieron retroalimentación significativa en la última semana están plenamente comprometidos. El momento lo es todo.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Qué decir</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;¿Tienes dos minutos? Esa instalación quedó muy bien y el cliente lo notó. Una cosa: la hoja de carga no coincidía con el camión, y la cuadrilla pasó cerca de una hora buscando piezas. La próxima vez, ¿puedes revisar la hoja antes de que salga el camión? ¿Qué te lo haría más fácil?&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Líder vs. jefe</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Buen trabajo.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Di esto:</b> La forma en que manejaste el recorrido con el cliente mantuvo todo el evento a tiempo.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Tienes que tener más cuidado.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Di esto:</b> La hoja de carga no coincidía con el camión. ¿Puedes revisarla antes de que salga la próxima vez?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>¿Por qué se atrasó otra vez?</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8F6A1C;\">Di esto:</b> ¿Qué se interpuso y qué necesitas de mí?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F8F3E8\" style=\"background:#F8F3E8;border-top:3px solid #C3922F;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Lo que debes saber</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">En California, los empleados actuales y anteriores pueden pedir ver su expediente de personal, y la empresa tiene 30 días para entregarlo (Código Laboral 1198.5). Todo lo que escribas sobre el desempeño de alguien puede terminar en sus manos. Escríbelo como si lo fuera a leer: específico, basado en hechos, sobre el trabajo y nunca sobre la persona.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #C3922F;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8F6A1C;\">Tu acción de 5 minutos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Elige a una persona de tu equipo, en la oficina o en la cuadrilla. Antes del viernes, dale una retroalimentación específica, positiva o de mejora, dentro de un día del momento. Que dure menos de dos minutos.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">¿Preguntas o algo con tu equipo que quieras conversar? Escríbele a Ben cuando quieras a <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#8F6A1C;font-weight:bold;\">ben@pendolinogroup.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Fuentes: <a href=\"https://brenebrown.com/articles/2018/10/15/clear-is-kind-unclear-is-unkind/\" style=\"color:#707070;\">Brené Brown</a> &middot; <a href=\"https://www.gallup.com/workplace/357764/fast-feedback-fuels-performance.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://law.justia.com/codes/california/code-lab/division-2/part-4/chapter-1/section-1198-5/\" style=\"color:#707070;\">Código Laboral de Cal. 1198.5</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Hensley Event Resources", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
    on conflict (id) do nothing;
  end if;
  select id into cid from public.clients where lower(name) = 'blueprint studios' limit 1;
  if cid is not null then
    insert into public.newsletters (id, client_id, created_by, data)
    values ('nl-2026-10-blueprint-intro-en-es', cid, 'ben@alzapc.com', $nl${"kind": "intro", "month": "2026-10", "lang": "en+es", "subject": "Introducing The Pause | Te presentamos La Pausa (English / Español)", "preview": "A few minutes each month, just for you. The first one lands in early October. Versión en español incluida.", "sendFrom": "hr@blueprintstudios.com", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Introducing The Pause | Te presentamos La Pausa (English / Español)</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">A few minutes each month, just for you. The first one lands in early October. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td height=\"6\" bgcolor=\"#1740F5\" style=\"background:#1740F5;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#1740F5;font-weight:bold;\">Blueprint Studios<br><span style=\"color:#707070;font-weight:normal;\">Starts October 2026</span></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#1740F5;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Introducing</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">A monthly time to pause</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">A few minutes each month that are just for you.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Work moves fast. It&#x27;s easy to go weeks without stopping to catch your breath, check in with the people around you, or think about how you&#x27;re actually doing.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">So we&#x27;re starting something new. Once a month you&#x27;ll get The Pause, a short email with one good idea, a couple of small things to try, and a little fun. It takes about three minutes to read, and there&#x27;s nothing you need to reply to.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">What&#x27;s inside</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">One idea backed by real research, something small to try, a way to get moving, a fun fact, and a simple challenge for the month.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">When it lands</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">The first week of every month, right here in your inbox. The first one arrives in early October.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C9D4FF;\">The only ask</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">When it shows up, give it three minutes. Try one thing. That&#x27;s it.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://my.adp.com\" style=\"color:#1740F5;font-weight:bold;\">Log in to ADP</a> or email <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#1740F5;\">HR@blueprintstudios.com</a>.<br>Have an idea for a future Pause? We&#x27;d love to hear it.</td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #1740F5;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Versión en español</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Te presentamos</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Un momento al mes para hacer una pausa</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Unos minutos cada mes que son solo para ti.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">El trabajo va rápido. Es fácil pasar semanas sin detenerte a respirar, saludar de verdad a quienes te rodean o pensar en cómo estás.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Por eso empezamos algo nuevo. Una vez al mes vas a recibir La Pausa, un correo corto con una buena idea, un par de cosas sencillas para probar y algo divertido. Se lee en unos tres minutos y no tienes que responder nada.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Qué trae</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Una idea respaldada por investigación real, algo pequeño para probar, una forma de moverte, un dato curioso y un reto sencillo para el mes.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Cuándo llega</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">La primera semana de cada mes, aquí en tu correo. La primera llega a principios de octubre.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C9D4FF;\">Lo único que pedimos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Cuando llegue, dale tres minutos. Prueba una cosa. Eso es todo.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">¿Necesitas algo? <a href=\"https://my.adp.com\" style=\"color:#1740F5;font-weight:bold;\">Entra a ADP</a> o escribe a <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#1740F5;\">HR@blueprintstudios.com</a>.<br>¿Tienes una idea para una próxima Pausa? Nos encantaría escucharla.</td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Introducing The Pause | Te presentamos La Pausa (English / Español)</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">A few minutes each month, just for you. The first one lands in early October. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td height=\"6\" bgcolor=\"#1740F5\" style=\"background:#1740F5;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#1740F5;font-weight:bold;\">Blueprint Studios<br><span style=\"color:#707070;font-weight:normal;\">Starts October 2026</span></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#1740F5;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Introducing</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">A monthly time to pause</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">A few minutes each month that are just for you.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Work moves fast. It&#x27;s easy to go weeks without stopping to catch your breath, check in with the people around you, or think about how you&#x27;re actually doing.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">So we&#x27;re starting something new. Once a month you&#x27;ll get The Pause, a short email with one good idea, a couple of small things to try, and a little fun. It takes about three minutes to read, and there&#x27;s nothing you need to reply to.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">What&#x27;s inside</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">One idea backed by real research, something small to try, a way to get moving, a fun fact, and a simple challenge for the month.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">When it lands</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">The first week of every month, right here in your inbox. The first one arrives in early October.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C9D4FF;\">The only ask</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">When it shows up, give it three minutes. Try one thing. That&#x27;s it.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://my.adp.com\" style=\"color:#1740F5;font-weight:bold;\">Log in to ADP</a> or email <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#1740F5;\">HR@blueprintstudios.com</a>.<br>Have an idea for a future Pause? We&#x27;d love to hear it.</td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #1740F5;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Versión en español</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Te presentamos</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Un momento al mes para hacer una pausa</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Unos minutos cada mes que son solo para ti.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">El trabajo va rápido. Es fácil pasar semanas sin detenerte a respirar, saludar de verdad a quienes te rodean o pensar en cómo estás.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Por eso empezamos algo nuevo. Una vez al mes vas a recibir La Pausa, un correo corto con una buena idea, un par de cosas sencillas para probar y algo divertido. Se lee en unos tres minutos y no tienes que responder nada.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Qué trae</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Una idea respaldada por investigación real, algo pequeño para probar, una forma de moverte, un dato curioso y un reto sencillo para el mes.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Cuándo llega</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">La primera semana de cada mes, aquí en tu correo. La primera llega a principios de octubre.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C9D4FF;\">Lo único que pedimos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Cuando llegue, dale tres minutos. Prueba una cosa. Eso es todo.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">¿Necesitas algo? <a href=\"https://my.adp.com\" style=\"color:#1740F5;font-weight:bold;\">Entra a ADP</a> o escribe a <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#1740F5;\">HR@blueprintstudios.com</a>.<br>¿Tienes una idea para una próxima Pausa? Nos encantaría escucharla.</td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Blueprint Studios", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
    on conflict (id) do nothing;
  end if;
  select id into cid from public.clients where lower(name) = 'blueprint studios' limit 1;
  if cid is not null then
    insert into public.newsletters (id, client_id, created_by, data)
    values ('nl-2026-10-blueprint-the-pause-en-es', cid, 'ben@alzapc.com', $nl${"kind": "the-pause", "month": "2026-10", "lang": "en+es", "subject": "The Pause: The people make the place | La Pausa (English / Español)", "preview": "Two minutes on connection, plus one small thing to try this week. Versión en español incluida.", "sendFrom": "hr@blueprintstudios.com", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>The Pause: The people make the place | La Pausa</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">Two minutes on connection, plus one small thing to try this week. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tbody><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tbody><tr><td height=\"6\" bgcolor=\"#1740F5\" style=\"background:#1740F5;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#1740F5;font-weight:bold;\">Blueprint Studios<br><span style=\"color:#707070;font-weight:normal;\">October 2026</span></td></tr></tbody></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></tbody></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#1740F5;font-weight:bold;text-decoration:none;\">Versión en español abajo ↓</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">New Monthly Email&nbsp;</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">A monthly time to take a quick pause..&nbsp;</h1><p style=\"margin: 0px 0px 16px; font-family: Arial, Helvetica, sans-serif; font-size: 17px; line-height: 1.6; color: rgb(43, 43, 43);\">Work moves fast at Blueprint Studios! It's easy to go weeks without stopping to catch your breath, check in with the people around you, or think about how you're actually doing.</p><p style=\"margin: 0px 0px 16px; font-family: Arial, Helvetica, sans-serif; font-size: 17px; line-height: 1.6; color: rgb(43, 43, 43);\">So we're starting something new. Once a month you'll get The Pause, a short email with a quick idea, a couple of small things to try, and a little fun. We hope this is something useful to you!&nbsp;</p></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">This month: Connection</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">The people make the place</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Small moments with the people around you add up.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard has been studying what makes people happy since 1938, following the same group for more than 80 years. The answer wasn't money or success. It was good relationships. And they don't have to be deep ones. A laugh during load-in, a real “how was your weekend,” or lunch with someone from the other side of the building all count.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Try this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Ask a coworker one question this week that isn't about work. \"What's keeping you busy outside of here?\" works. Then actually listen to the answer.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Get moving</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Take a 10-minute walk or a coffee run with someone from the office. On the warehouse floor or out on an install? Take your next break with someone from the crew. A Stanford study found walking boosted creative ideas by about 60%.</p></td></tr></tbody></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Worth knowing</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#1740F5;\">Fun fact</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">People laugh about 30 times more often with others than when they're alone, according to laughter researcher Robert Provine. Good company is contagious.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#1740F5;\">Oct 10</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">World Mental Health Day. A good excuse to check in on someone, including yourself.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#1740F5;\">Nov 1</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Clocks fall back an hour. Enjoy the extra sleep.</td></tr></tbody></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C9D4FF;\">Your challenge</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Connect with 3 people this month you don't usually talk to. In the office? Go say hi to someone in the warehouse. On the crew? Stop by the office. A quick hello counts.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://my.adp.com\" style=\"color:#1740F5;font-weight:bold;\">Log in to ADP</a> or email <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#1740F5;\">HR@blueprintstudios.com</a>.<br>Carrying something heavier? Reach out to HR. We're here to help.<br><br><span style=\"font-size:11px;\">Sources: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> · <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> · <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> · <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td style=\"border-top:6px solid #1740F5;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Versión en español</p></td></tr></tbody></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Este mes: Conexión</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Las personas hacen el lugar</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Los pequeños momentos con quienes te rodean suman.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard lleva desde 1938 estudiando qué hace feliz a la gente, siguiendo al mismo grupo por más de 80 años. La respuesta no fue el dinero ni el éxito. Fueron las buenas relaciones. Y no tienen que ser profundas. Una risa durante el montaje, un “¿qué tal tu fin de semana?” sincero o un almuerzo con alguien del otro lado del edificio cuentan.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Prueba esto</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Esta semana, hazle a un compañero una pregunta que no sea de trabajo. \"¿Qué te tiene ocupado fuera de aquí?\" funciona. Luego escucha de verdad la respuesta.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Muévete</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Sal a caminar 10 minutos o por un café con alguien de la oficina. ¿En el almacén o en una instalación? Toma tu próximo descanso con alguien de la cuadrilla. Un estudio de Stanford encontró que caminar aumentó las ideas creativas en cerca de un 60%.</p></td></tr></tbody></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Bueno saber</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#1740F5;\">Dato curioso</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Según el investigador Robert Provine, las personas se ríen unas 30 veces más cuando están con otros que cuando están solas. La buena compañía se contagia.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#1740F5;\">10 oct</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Día Mundial de la Salud Mental. Un buen pretexto para preguntarle a alguien cómo está, incluyéndote a ti.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#1740F5;\">1 nov</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Se atrasan los relojes una hora. Disfruta el sueño extra.</td></tr></tbody></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C9D4FF;\">Tu reto</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Conecta este mes con 3 personas con las que normalmente no hablas. ¿Estás en la oficina? Ve a saludar a alguien del almacén. ¿Estás en la cuadrilla? Pasa por la oficina. Un simple saludo cuenta.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">¿Necesitas algo? <a href=\"https://my.adp.com\" style=\"color:#1740F5;font-weight:bold;\">Entra a ADP</a> o escribe a <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#1740F5;\">HR@blueprintstudios.com</a>.<br>¿Cargas con algo más pesado? Escríbenos. Estamos para ayudarte.<br><br><span style=\"font-size:11px;\">Fuentes: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> · <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> · <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> · <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a></span></td></tr><!--/BODY-->\n</tbody></table></td></tr></tbody></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>The Pause: The people make the place | La Pausa</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">Two minutes on connection, plus one small thing to try this week. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td height=\"6\" bgcolor=\"#1740F5\" style=\"background:#1740F5;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#1740F5;font-weight:bold;\">Blueprint Studios<br><span style=\"color:#707070;font-weight:normal;\">October 2026</span></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#1740F5;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">This month: Connection</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">The people make the place</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Small moments with the people around you add up.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard has been studying what makes people happy since 1938, following the same group for more than 80 years. The answer wasn&#x27;t money or success. It was good relationships. And they don&#x27;t have to be deep ones. A laugh during load-in, a real “how was your weekend,” or lunch with someone from the other side of the building all count.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Try this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Ask a coworker one question this week that isn&#x27;t about work. &quot;What&#x27;s keeping you busy outside of here?&quot; works. Then actually listen to the answer.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Get moving</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Take a 10-minute walk or a coffee run with someone from the office. On the warehouse floor or out on an install? Take your next break with someone from the crew. A Stanford study found walking boosted creative ideas by about 60%.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Worth knowing</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#1740F5;\">Fun fact</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">People laugh about 30 times more often with others than when they&#x27;re alone, according to laughter researcher Robert Provine. Good company is contagious.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#1740F5;\">Oct 10</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">World Mental Health Day. A good excuse to check in on someone, including yourself.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#1740F5;\">Nov 1</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Clocks fall back an hour. Enjoy the extra sleep.</td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C9D4FF;\">Your challenge</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Connect with 3 people this month you don&#x27;t usually talk to. In the office? Go say hi to someone in the warehouse. On the crew? Stop by the office. A quick hello counts.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://my.adp.com\" style=\"color:#1740F5;font-weight:bold;\">Log in to ADP</a> or email <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#1740F5;\">HR@blueprintstudios.com</a>.<br>Carrying something heavier? Reach out to HR. We&#x27;re here to help.<br><br><span style=\"font-size:11px;\">Sources: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> &middot; <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> &middot; <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> &middot; <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #1740F5;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Versión en español</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Este mes: Conexión</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Las personas hacen el lugar</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Los pequeños momentos con quienes te rodean suman.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard lleva desde 1938 estudiando qué hace feliz a la gente, siguiendo al mismo grupo por más de 80 años. La respuesta no fue el dinero ni el éxito. Fueron las buenas relaciones. Y no tienen que ser profundas. Una risa durante el montaje, un “¿qué tal tu fin de semana?” sincero o un almuerzo con alguien del otro lado del edificio cuentan.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Prueba esto</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Esta semana, hazle a un compañero una pregunta que no sea de trabajo. &quot;¿Qué te tiene ocupado fuera de aquí?&quot; funciona. Luego escucha de verdad la respuesta.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Muévete</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Sal a caminar 10 minutos o por un café con alguien de la oficina. ¿En el almacén o en una instalación? Toma tu próximo descanso con alguien de la cuadrilla. Un estudio de Stanford encontró que caminar aumentó las ideas creativas en cerca de un 60%.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Bueno saber</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#1740F5;\">Dato curioso</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Según el investigador Robert Provine, las personas se ríen unas 30 veces más cuando están con otros que cuando están solas. La buena compañía se contagia.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#1740F5;\">10 oct</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Día Mundial de la Salud Mental. Un buen pretexto para preguntarle a alguien cómo está, incluyéndote a ti.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#1740F5;\">1 nov</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Se atrasan los relojes una hora. Disfruta el sueño extra.</td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C9D4FF;\">Tu reto</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Conecta este mes con 3 personas con las que normalmente no hablas. ¿Estás en la oficina? Ve a saludar a alguien del almacén. ¿Estás en la cuadrilla? Pasa por la oficina. Un simple saludo cuenta.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">¿Necesitas algo? <a href=\"https://my.adp.com\" style=\"color:#1740F5;font-weight:bold;\">Entra a ADP</a> o escribe a <a href=\"mailto:HR@blueprintstudios.com\" style=\"color:#1740F5;\">HR@blueprintstudios.com</a>.<br>¿Cargas con algo más pesado? Escríbenos. Estamos para ayudarte.<br><br><span style=\"font-size:11px;\">Fuentes: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> &middot; <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> &middot; <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> &middot; <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Blueprint Studios", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
    on conflict (id) do nothing;
  end if;
  select id into cid from public.clients where lower(name) = 'blueprint studios' limit 1;
  if cid is not null then
    insert into public.newsletters (id, client_id, created_by, data)
    values ('nl-2026-10-blueprint-manager-minute-en-es', cid, 'ben@alzapc.com', $nl${"kind": "manager-minute", "month": "2026-10", "lang": "en+es", "subject": "Manager Minute: Feedback that actually lands | Minuto del Líder (English / Español)", "preview": "One script, one swap, and a 5-minute move for this week. Versión en español incluida.", "sendFrom": "hr@blueprintstudios.com", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Feedback that actually lands | Minuto del Líder</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One script, one swap, and a 5-minute move for this week. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#C9D4FF;font-weight:bold;\">Blueprint Studios<br><span style=\"font-weight:normal;\">October 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C9D4FF;\">This month: Feedback</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Feedback that actually lands</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#1740F5;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Clear is kind. Unclear is unkind.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Brené Brown, Dare to Lead</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Your install lead did great work on a big event last weekend. But the load-out sheet didn&#x27;t match what went on the truck, and the crew lost about an hour tracking down missing pieces. You&#x27;ve been meaning to say something. It&#x27;s been five days.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#1740F5;\">Why it matters.</b> Gallup found that 80% of employees who got meaningful feedback in the past week are fully engaged. Timing is half the battle.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;Got two minutes? That install looked great, and the client noticed. One thing: the load-out sheet didn&#x27;t match the truck, and the crew spent about an hour hunting for pieces. Next time, can you double-check the sheet before the truck leaves? What would make that easier?&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Good job.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Say this:</b> The way you handled that client walkthrough kept the whole event on schedule.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>You need to be more careful.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Say this:</b> The load-out sheet didn&#x27;t match the truck. Can you check it before it leaves next time?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Why is this late again?</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Say this:</b> What got in the way, and what do you need from me?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">In both California and Nevada, employees have the right to see their personnel file. California gives the company 30 days to produce it (Labor Code 1198.5), and Nevada requires reasonable access during business hours (NRS 613.075). Either way, anything you write about someone&#x27;s performance may end up in front of them. Write it like they&#x27;ll read it: specific, factual, about the work, never the person.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #1740F5;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Pick one person on your team, in the office or on the crew. Before Friday, give them one specific piece of feedback, positive or corrective, within a day of the moment. Keep it under two minutes.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to Ben and Nelda anytime at <a href=\"mailto:hr@blueprintstudios.com\" style=\"color:#1740F5;font-weight:bold;\">hr@blueprintstudios.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://brenebrown.com/articles/2018/10/15/clear-is-kind-unclear-is-unkind/\" style=\"color:#707070;\">Brené Brown</a> &middot; <a href=\"https://www.gallup.com/workplace/357764/fast-feedback-fuels-performance.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://law.justia.com/codes/california/code-lab/division-2/part-4/chapter-1/section-1198-5/\" style=\"color:#707070;\">Cal. Labor Code 1198.5</a> &middot; <a href=\"https://www.leg.state.nv.us/nrs/nrs-613.html\" style=\"color:#707070;\">Nev. Rev. Stat. 613.075</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #1740F5;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Versión en español</p><h2 style=\"margin:6px 0 0 0;font-family:Georgia, 'Times New Roman', serif;font-size:28px;font-weight:normal;line-height:1.2;color:#2B2B2B;\">Minuto del Líder: Retroalimentación que sí llega</h2></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Ser claro es ser amable. No serlo, no lo es.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Brené Brown, Dare to Lead (traducción)</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Tu líder de instalación hizo un gran trabajo en un evento grande el fin de semana pasado. Pero la hoja de carga no coincidía con lo que subió al camión, y la cuadrilla perdió cerca de una hora buscando piezas. Has querido decir algo. Ya pasaron cinco días.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#1740F5;\">Por qué importa.</b> Gallup encontró que el 80% de los empleados que recibieron retroalimentación significativa en la última semana están plenamente comprometidos. El momento lo es todo.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Qué decir</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;¿Tienes dos minutos? Esa instalación quedó muy bien y el cliente lo notó. Una cosa: la hoja de carga no coincidía con el camión, y la cuadrilla pasó cerca de una hora buscando piezas. La próxima vez, ¿puedes revisar la hoja antes de que salga el camión? ¿Qué te lo haría más fácil?&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Líder vs. jefe</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Buen trabajo.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Di esto:</b> La forma en que manejaste el recorrido con el cliente mantuvo todo el evento a tiempo.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Tienes que tener más cuidado.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Di esto:</b> La hoja de carga no coincidía con el camión. ¿Puedes revisarla antes de que salga la próxima vez?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>¿Por qué se atrasó otra vez?</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Di esto:</b> ¿Qué se interpuso y qué necesitas de mí?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Lo que debes saber</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Tanto en California como en Nevada, los empleados tienen derecho a ver su expediente de personal. California le da a la empresa 30 días para entregarlo (Código Laboral 1198.5) y Nevada exige dar acceso razonable en horario laboral (NRS 613.075). En cualquier caso, todo lo que escribas sobre el desempeño de alguien puede terminar en sus manos. Escríbelo como si lo fuera a leer: específico, basado en hechos, sobre el trabajo y nunca sobre la persona.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #1740F5;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Tu acción de 5 minutos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Elige a una persona de tu equipo, en la oficina o en la cuadrilla. Antes del viernes, dale una retroalimentación específica, positiva o de mejora, dentro de un día del momento. Que dure menos de dos minutos.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">¿Preguntas o algo con tu equipo que quieras conversar? Escríbeles a Ben y Nelda cuando quieras a <a href=\"mailto:hr@blueprintstudios.com\" style=\"color:#1740F5;font-weight:bold;\">hr@blueprintstudios.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Fuentes: <a href=\"https://brenebrown.com/articles/2018/10/15/clear-is-kind-unclear-is-unkind/\" style=\"color:#707070;\">Brené Brown</a> &middot; <a href=\"https://www.gallup.com/workplace/357764/fast-feedback-fuels-performance.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://law.justia.com/codes/california/code-lab/division-2/part-4/chapter-1/section-1198-5/\" style=\"color:#707070;\">Código Laboral de Cal. 1198.5</a> &middot; <a href=\"https://www.leg.state.nv.us/nrs/nrs-613.html\" style=\"color:#707070;\">Nev. Rev. Stat. 613.075</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Feedback that actually lands | Minuto del Líder</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">One script, one swap, and a 5-minute move for this week. Versión en español incluida.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#1740F5\" style=\"background:#1740F5;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#C9D4FF;font-weight:bold;\">Blueprint Studios<br><span style=\"font-weight:normal;\">October 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#C9D4FF;\">This month: Feedback</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Feedback that actually lands</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:14px 40px 0 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;color:#707070;\"><a href=\"#es\" style=\"color:#1740F5;font-weight:bold;text-decoration:none;\">Versión en español abajo &darr;</a></td></tr><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Clear is kind. Unclear is unkind.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Brené Brown, Dare to Lead</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Your install lead did great work on a big event last weekend. But the load-out sheet didn&#x27;t match what went on the truck, and the crew lost about an hour tracking down missing pieces. You&#x27;ve been meaning to say something. It&#x27;s been five days.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#1740F5;\">Why it matters.</b> Gallup found that 80% of employees who got meaningful feedback in the past week are fully engaged. Timing is half the battle.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;Got two minutes? That install looked great, and the client noticed. One thing: the load-out sheet didn&#x27;t match the truck, and the crew spent about an hour hunting for pieces. Next time, can you double-check the sheet before the truck leaves? What would make that easier?&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Good job.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Say this:</b> The way you handled that client walkthrough kept the whole event on schedule.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>You need to be more careful.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Say this:</b> The load-out sheet didn&#x27;t match the truck. Can you check it before it leaves next time?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Why is this late again?</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Say this:</b> What got in the way, and what do you need from me?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">In both California and Nevada, employees have the right to see their personnel file. California gives the company 30 days to produce it (Labor Code 1198.5), and Nevada requires reasonable access during business hours (NRS 613.075). Either way, anything you write about someone&#x27;s performance may end up in front of them. Write it like they&#x27;ll read it: specific, factual, about the work, never the person.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #1740F5;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Pick one person on your team, in the office or on the crew. Before Friday, give them one specific piece of feedback, positive or corrective, within a day of the moment. Keep it under two minutes.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to Ben and Nelda anytime at <a href=\"mailto:hr@blueprintstudios.com\" style=\"color:#1740F5;font-weight:bold;\">hr@blueprintstudios.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://brenebrown.com/articles/2018/10/15/clear-is-kind-unclear-is-unkind/\" style=\"color:#707070;\">Brené Brown</a> &middot; <a href=\"https://www.gallup.com/workplace/357764/fast-feedback-fuels-performance.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://law.justia.com/codes/california/code-lab/division-2/part-4/chapter-1/section-1198-5/\" style=\"color:#707070;\">Cal. Labor Code 1198.5</a> &middot; <a href=\"https://www.leg.state.nv.us/nrs/nrs-613.html\" style=\"color:#707070;\">Nev. Rev. Stat. 613.075</a></span></td></tr><tr><td class=\"pad\" style=\"padding:40px 40px 0 40px;\"><a name=\"es\" id=\"es\"></a><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-top:6px solid #1740F5;padding-top:18px;\"><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Versión en español</p><h2 style=\"margin:6px 0 0 0;font-family:Georgia, 'Times New Roman', serif;font-size:28px;font-weight:normal;line-height:1.2;color:#2B2B2B;\">Minuto del Líder: Retroalimentación que sí llega</h2></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">&ldquo;Ser claro es ser amable. No serlo, no lo es.&rdquo;</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Brené Brown, Dare to Lead (traducción)</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Tu líder de instalación hizo un gran trabajo en un evento grande el fin de semana pasado. Pero la hoja de carga no coincidía con lo que subió al camión, y la cuadrilla perdió cerca de una hora buscando piezas. Has querido decir algo. Ya pasaron cinco días.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#1740F5;\">Por qué importa.</b> Gallup encontró que el 80% de los empleados que recibieron retroalimentación significativa en la última semana están plenamente comprometidos. El momento lo es todo.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Qué decir</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;¿Tienes dos minutos? Esa instalación quedó muy bien y el cliente lo notó. Una cosa: la hoja de carga no coincidía con el camión, y la cuadrilla pasó cerca de una hora buscando piezas. La próxima vez, ¿puedes revisar la hoja antes de que salga el camión? ¿Qué te lo haría más fácil?&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Líder vs. jefe</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Buen trabajo.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Di esto:</b> La forma en que manejaste el recorrido con el cliente mantuvo todo el evento a tiempo.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>Tienes que tener más cuidado.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Di esto:</b> La hoja de carga no coincidía con el camión. ¿Puedes revisarla antes de que salga la próxima vez?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">No esto:</b> <s>¿Por qué se atrasó otra vez?</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#1740F5;\">Di esto:</b> ¿Qué se interpuso y qué necesitas de mí?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#EEF2FF\" style=\"background:#EEF2FF;border-top:3px solid #1740F5;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Lo que debes saber</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Tanto en California como en Nevada, los empleados tienen derecho a ver su expediente de personal. California le da a la empresa 30 días para entregarlo (Código Laboral 1198.5) y Nevada exige dar acceso razonable en horario laboral (NRS 613.075). En cualquier caso, todo lo que escribas sobre el desempeño de alguien puede terminar en sus manos. Escríbelo como si lo fuera a leer: específico, basado en hechos, sobre el trabajo y nunca sobre la persona.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #1740F5;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#1740F5;\">Tu acción de 5 minutos</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Elige a una persona de tu equipo, en la oficina o en la cuadrilla. Antes del viernes, dale una retroalimentación específica, positiva o de mejora, dentro de un día del momento. Que dure menos de dos minutos.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">¿Preguntas o algo con tu equipo que quieras conversar? Escríbeles a Ben y Nelda cuando quieras a <a href=\"mailto:hr@blueprintstudios.com\" style=\"color:#1740F5;font-weight:bold;\">hr@blueprintstudios.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Fuentes: <a href=\"https://brenebrown.com/articles/2018/10/15/clear-is-kind-unclear-is-unkind/\" style=\"color:#707070;\">Brené Brown</a> &middot; <a href=\"https://www.gallup.com/workplace/357764/fast-feedback-fuels-performance.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://law.justia.com/codes/california/code-lab/division-2/part-4/chapter-1/section-1198-5/\" style=\"color:#707070;\">Código Laboral de Cal. 1198.5</a> &middot; <a href=\"https://www.leg.state.nv.us/nrs/nrs-613.html\" style=\"color:#707070;\">Nev. Rev. Stat. 613.075</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Blueprint Studios", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
    on conflict (id) do nothing;
  end if;
  select id into cid from public.clients where lower(name) in ('students run la','srla') limit 1;
  if cid is not null then
    insert into public.newsletters (id, client_id, created_by, data)
    values ('nl-2026-10-srla-intro-en', cid, 'ben@alzapc.com', $nl${"kind": "intro", "month": "2026-10", "lang": "en", "subject": "Introducing The Pause", "preview": "A few minutes each month, just for you. The first one lands in early October.", "sendFrom": "Pendolino (ben@pendolinogroup.com)", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Introducing The Pause</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">A few minutes each month, just for you. The first one lands in early October.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td height=\"6\" bgcolor=\"#000000\" style=\"background:#000000;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#000000;font-weight:bold;\">Students Run LA<br><span style=\"color:#707070;font-weight:normal;\">Starts October 2026</span></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Introducing</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">A monthly time to pause</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">A few minutes each month that are just for you.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Work moves fast. It&#x27;s easy to go weeks without stopping to catch your breath, check in with the people around you, or think about how you&#x27;re actually doing.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">So we&#x27;re starting something new. Once a month you&#x27;ll get The Pause, a short email with one good idea, a couple of small things to try, and a little fun. It takes about three minutes to read, and there&#x27;s nothing you need to reply to.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">What&#x27;s inside</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">One idea backed by real research, something small to try, a way to get moving, a fun fact, and a simple challenge for the month.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">When it lands</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">The first week of every month, right here in your inbox. The first one arrives in early October.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#000000\" style=\"background:#000000;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#D9FE52;\">The only ask</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">When it shows up, give it three minutes. Try one thing. That&#x27;s it.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://my.adp.com\" style=\"color:#000000;font-weight:bold;\">Log in to ADP</a> or reach out to Ben at <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#000000;\">ben@pendolinogroup.com</a>.<br>Have an idea for a future Pause? Send it to Ben. He&#x27;d love to hear it.</td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Introducing The Pause</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">A few minutes each month, just for you. The first one lands in early October.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td height=\"6\" bgcolor=\"#000000\" style=\"background:#000000;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#000000;font-weight:bold;\">Students Run LA<br><span style=\"color:#707070;font-weight:normal;\">Starts October 2026</span></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Introducing</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">A monthly time to pause</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">A few minutes each month that are just for you.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Work moves fast. It&#x27;s easy to go weeks without stopping to catch your breath, check in with the people around you, or think about how you&#x27;re actually doing.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">So we&#x27;re starting something new. Once a month you&#x27;ll get The Pause, a short email with one good idea, a couple of small things to try, and a little fun. It takes about three minutes to read, and there&#x27;s nothing you need to reply to.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">What&#x27;s inside</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">One idea backed by real research, something small to try, a way to get moving, a fun fact, and a simple challenge for the month.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">When it lands</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">The first week of every month, right here in your inbox. The first one arrives in early October.</p></td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#000000\" style=\"background:#000000;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#D9FE52;\">The only ask</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">When it shows up, give it three minutes. Try one thing. That&#x27;s it.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://my.adp.com\" style=\"color:#000000;font-weight:bold;\">Log in to ADP</a> or reach out to Ben at <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#000000;\">ben@pendolinogroup.com</a>.<br>Have an idea for a future Pause? Send it to Ben. He&#x27;d love to hear it.</td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Students Run LA", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
