    values ('nl-2026-10-srla-the-pause-en', cid, 'ben@alzapc.com', $nl${"kind": "the-pause", "month": "2026-10", "lang": "en", "subject": "The Pause: Nobody runs alone", "preview": "A few minutes on sticking together, plus one easy way to check in on someone this week.", "sendFrom": "Pendolino (ben@pendolinogroup.com)", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>The Pause: Nobody runs alone</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">A few minutes on sticking together, plus one easy way to check in on someone this week.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tbody><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tbody><tr><td height=\"6\" bgcolor=\"#000000\" style=\"background:#000000;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#000000;font-weight:bold;\">Students Run LA<br><span style=\"color:#707070;font-weight:normal;\">October 2026</span></td></tr></tbody></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></tbody></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">This month: Sticking together</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Nobody runs alone</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Tough seasons go better when we look out for each other.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard has been studying what makes people happy since 1938, following the same group for more than 80 years. The answer wasn't money or success. It was good relationships, and those ties helped protect people when life got hard. At work that can be as simple as a real \"how are you doing?\", a laugh in the office, or covering for someone who's stretched thin.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Try this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Check in on a coworker this week. Not about a project or a deadline. Just: \"How are you doing, really?\" Then actually listen. It takes two minutes and it matters more than you think.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Get moving</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Grab a coworker for a 10-minute walk or a coffee run. You keep programs going for thousands of kids all year. Take ten minutes for the two of you. A Stanford study found walking boosted creative ideas by about 60%.</p></td></tr></tbody></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Worth knowing</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tbody><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#000000;\">Fun fact</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">People laugh about 30 times more often with others than when they're alone, according to laughter researcher Robert Provine. Good company is contagious.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#000000;\">Running fact</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Why is a marathon 26.2 miles? At the 1908 London Olympics, the course was laid out to start at Windsor Castle and finish in front of the royal box, so the royal family had a good view. The odd distance stuck.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#000000;\">Oct 10</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">World Mental Health Day. A good excuse to check in on someone, including yourself.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#000000;\">Nov 1</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Clocks fall back an hour. Enjoy the extra sleep.</td></tr></tbody></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#000000\" style=\"background:#000000;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#D9FE52;\">Your challenge</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Check in on a coworker this month you haven't really caught up with lately. A quick call, a text, a coffee. Ask how they're doing and mean it. Nobody runs this race alone.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://my.adp.com\" style=\"color:#000000;font-weight:bold;\">Log in to ADP</a> or reach out to Ben at <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#000000;\">ben@pendolinogroup.com</a>.<br>Carrying something heavier? Reach out to Ben anytime. Always happy to help.<br><br><span style=\"font-size:11px;\">Sources: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> · <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> · <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> · <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a> · <a href=\"https://www.britannica.com/sports/Why-Is-a-Marathon-26-2-Miles\" style=\"color:#707070;\">Britannica</a></span></td></tr><!--/BODY-->\n</tbody></table></td></tr></tbody></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>The Pause: Nobody runs alone</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">A few minutes on sticking together, plus one easy way to check in on someone this week.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td height=\"6\" bgcolor=\"#000000\" style=\"background:#000000;font-size:0;line-height:0;\">&nbsp;</td></tr>\n<tr><td class=\"pad\" style=\"padding:26px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr>\n<td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:24px;color:#2B2B2B;\">The Pause</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#000000;font-weight:bold;\">Students Run LA<br><span style=\"color:#707070;font-weight:normal;\">October 2026</span></td></tr></table>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border-bottom:1px solid #E6E6E6;padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr></table></td></tr>\n<!--BODY--><tr><td class=\"pad\" style=\"padding:30px 40px 4px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">This month: Sticking together</p><h1 style=\"margin:0 0 10px 0;font-family:Georgia, 'Times New Roman', serif;font-size:36px;font-weight:normal;line-height:1.15;color:#2B2B2B;\">Nobody runs alone</h1><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:19px;line-height:1.6;color:#707070;font-style:italic;margin-bottom:24px;\">Busy seasons go better when we look out for each other.</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">Harvard has been studying what makes people happy since 1938, following the same group for more than 80 years. The answer wasn&#x27;t money or success. It was good relationships, and those ties helped protect people when life got hard. At work that can be as simple as a real &quot;how are you doing?&quot;, a laugh in the office, or covering for someone who&#x27;s stretched thin.</p></td></tr><tr><td class=\"pad\" style=\"padding:6px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Try this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Check in on a coworker this week. Not about a project or a deadline. Just: &quot;How are you doing, really?&quot; Then actually listen. It takes two minutes and it matters more than you think.</p></td><td class=\"gap\" width=\"16\" bgcolor=\"#FFFFFF\" style=\"width:16px;min-width:16px;background:#FFFFFF;font-size:0;line-height:0;\">&nbsp;</td><td class=\"col\" valign=\"top\" width=\"47%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Get moving</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">Grab a coworker for a 10-minute walk or a coffee run. You keep programs going for thousands of kids all year. Take ten minutes for the two of you. A Stanford study found walking boosted creative ideas by about 60%.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Worth knowing</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#000000;\">Fun fact</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">People laugh about 30 times more often with others than when they&#x27;re alone, according to laughter researcher Robert Provine. Good company is contagious.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#000000;\">Running fact</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Why is a marathon 26.2 miles? At the 1908 London Olympics, the course was laid out to start at Windsor Castle and finish in front of the royal box, so the royal family had a good view. The odd distance stuck.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#000000;\">Oct 10</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">World Mental Health Day. A good excuse to check in on someone, including yourself.</td></tr><tr><td valign=\"top\" width=\"92\" style=\"padding:10px 12px 10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:13px;font-weight:bold;color:#000000;\">Nov 1</td><td style=\"padding:10px 0;border-top:1px solid #E6E6E6;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.5;color:#2B2B2B;\">Clocks fall back an hour. Enjoy the extra sleep.</td></tr></table></td></tr><tr><td style=\"padding-top:18px;font-size:0;line-height:0;\">&nbsp;</td></tr><tr><td class=\"pad\" bgcolor=\"#000000\" style=\"background:#000000;padding:28px 40px 30px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#D9FE52;\">Your challenge</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.5;color:#FFFFFF;\">Check in on 3 coworkers this month you haven&#x27;t really caught up with lately. A quick call, a text, a coffee. Ask how they&#x27;re doing and mean it. Nobody runs this race alone.</p></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.7;color:#707070;\">Need something? <a href=\"https://my.adp.com\" style=\"color:#000000;font-weight:bold;\">Log in to ADP</a> or reach out to Ben at <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#000000;\">ben@pendolinogroup.com</a>.<br>Carrying something heavier? Reach out to Ben anytime. Happy to help.<br><br><span style=\"font-size:11px;\">Sources: <a href=\"https://news.harvard.edu/gazette/story/2017/04/over-nearly-80-years-harvard-study-has-been-showing-how-to-live-a-healthy-and-happy-life/\" style=\"color:#707070;\">Harvard Gazette</a> &middot; <a href=\"https://news.stanford.edu/stories/2014/04/walking-vs-sitting-042414\" style=\"color:#707070;\">Stanford, 2014</a> &middot; <a href=\"https://www.psychologytoday.com/us/articles/200011/the-science-of-laughter\" style=\"color:#707070;\">Psychology Today</a> &middot; <a href=\"https://www.who.int/campaigns/world-mental-health-day\" style=\"color:#707070;\">WHO</a> &middot; <a href=\"https://www.britannica.com/sports/Why-Is-a-Marathon-26-2-Miles\" style=\"color:#707070;\">Britannica</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Students Run LA", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
    on conflict (id) do nothing;
  end if;
  select id into cid from public.clients where lower(name) in ('students run la','srla') limit 1;
  if cid is not null then
    insert into public.newsletters (id, client_id, created_by, data)
    values ('nl-2026-10-srla-manager-minute-en', cid, 'ben@alzapc.com', $nl${"kind": "manager-minute", "month": "2026-10", "lang": "en", "subject": "Manager Minute: Keeping your team together", "preview": "A simple check-in that helps your team feel supported, plus one 5-minute move for this month.", "sendFrom": "Pendolino (ben@pendolinogroup.com)", "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Keeping your team together</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">A simple check-in that helps your team feel supported, plus one 5-minute move for this month.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#000000\" style=\"background:#000000;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#D9FE52;font-weight:bold;\">Students Run LA<br><span style=\"font-weight:normal;\">October 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#D9FE52;\">This month: Sticking together</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Keeping your team together</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">“Alone we can do so little; together we can do so much.”</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Helen Keller</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">It&#x27;s been a demanding stretch. Your team is keeping programs running for thousands of students, working with school partners, and handling a few tough volunteer conversations along the way. Everyone&#x27;s still showing up, but you can tell some people are running low, and a couple have gone a little quiet.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#000000;\">Why it matters.</b> Gallup found managers account for 70% of the variance in team engagement. When things get busy, a quick check-in from you goes a long way.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;Hey, wanted to check in. It&#x27;s been a busy stretch and I know you&#x27;ve been carrying a lot. How are you doing, really? Anything I can help with or take off your plate this week?&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Everyone just needs to push through.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#000000;\">Say this:</b> It&#x27;s been a lot. Let&#x27;s figure out what we can lighten up.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Just ignore them.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#000000;\">Say this:</b> That sounded like a tough conversation. Want to walk me through it?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Let me know if you need anything.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#000000;\">Say this:</b> Let&#x27;s grab 10 minutes Thursday. What&#x27;s one thing I can help with?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">In California, an employer can be responsible when a non-employee, like a volunteer, harasses staff, if a supervisor knows or should have known and doesn&#x27;t take quick, appropriate action (Gov. Code 12940(j)). Most tough volunteer conversations aren&#x27;t harassment. But if one crosses the line, don&#x27;t sit on it. Write down what happened and loop in Ben the same day.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #000000;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Before the end of the month, take 5 minutes with each person on your team. No agenda. Ask how they&#x27;re doing, thank them for one specific thing, and ask what would help.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to Ben anytime at <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#000000;font-weight:bold;\">ben@pendolinogroup.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://afb.org/about-afb/history/helen-keller/helen-keller-quotes/helen-keller-quotes-progress\" style=\"color:#707070;\">Helen Keller (AFB)</a> &middot; <a href=\"https://www.gallup.com/workplace/713033/managers-and-team-productivity.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=GOV&amp;sectionNum=12940\" style=\"color:#707070;\">Cal. Gov. Code 12940</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "originalHtml": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Manager Minute: Keeping your team together</title>\n<style>@media (max-width:620px){.col{display:block!important;width:auto!important}.gap{display:block!important;height:14px!important;width:auto!important}.pad{padding-left:24px!important;padding-right:24px!important}.hdr{display:block!important;width:auto!important;text-align:left!important;padding-bottom:6px!important}}</style></head>\n<body style=\"margin:0;padding:0;background:#F4F4F4;\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0;\">A simple check-in that helps your team feel supported, plus one 5-minute move for this month.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#F4F4F4\"><tr><td align=\"center\" style=\"padding:28px 10px;\">\n<table role=\"presentation\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" bgcolor=\"#FFFFFF\" style=\"width:100%;max-width:600px;background:#FFFFFF;\">\n<tr><td class=\"pad\" bgcolor=\"#000000\" style=\"background:#000000;padding:24px 40px 32px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"hdr\" style=\"font-family:Georgia, 'Times New Roman', serif;font-size:22px;color:#FFFFFF;\">Manager Minute</td>\n<td class=\"hdr\" align=\"right\" style=\"font-family:Arial, Helvetica, sans-serif;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#D9FE52;font-weight:bold;\">Students Run LA<br><span style=\"font-weight:normal;\">October 2026</span></td></tr></table><p style=\"margin:30px 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#D9FE52;\">This month: Sticking together</p><h1 style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:34px;font-weight:normal;line-height:1.15;color:#FFFFFF;\">Keeping your team together</h1></td></tr><!--BODY--><tr><td class=\"pad\" style=\"padding:30px 40px 0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Georgia, 'Times New Roman', serif;font-size:21px;line-height:1.6;color:#2B2B2B;font-style:italic;margin-bottom:4px;\">“Alone we can do so little; together we can do so much.”</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:13px;line-height:1.6;color:#707070;margin-bottom:24px;\">Helen Keller</p></td></tr><tr><td class=\"pad\" style=\"padding:0 40px;\"><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:17px;line-height:1.6;color:#2B2B2B;\">It&#x27;s been a demanding stretch. Your team is keeping programs running for thousands of students, working with school partners, and handling a few tough volunteer conversations along the way. Everyone&#x27;s still showing up, but you can tell some people are running low, and a couple have gone a little quiet.</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#707070;\"><b style=\"color:#000000;\">Why it matters.</b> Gallup found managers account for 70% of the variance in team engagement. When things get busy, a quick check-in from you goes a long way.</p></td></tr><tr><td class=\"pad\" style=\"padding:4px 40px 10px 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">What to say</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\"><i>&quot;Hey, wanted to check in. It&#x27;s been a busy stretch and I know you&#x27;ve been carrying a lot. How are you doing, really? Anything I can help with or take off your plate this week?&quot;</i></p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:22px 40px 6px 40px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Leader vs. manager</p><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Everyone just needs to push through.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#000000;\">Say this:</b> It&#x27;s been a lot. Let&#x27;s figure out what we can lighten up.</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Just ignore them.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#000000;\">Say this:</b> That sounded like a tough conversation. Want to walk me through it?</p></td></tr><tr><td style=\"padding:12px 0;border-top:1px solid #E6E6E6;\"><p style=\"margin:0 0 4px 0;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.5;color:#707070;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;\">Not that:</b> <s>Let me know if you need anything.</s></p><p style=\"margin:0;font-family:Arial, Helvetica, sans-serif;font-size:16px;line-height:1.5;color:#2B2B2B;\"><b style=\"font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#000000;\">Say this:</b> Let&#x27;s grab 10 minutes Thursday. What&#x27;s one thing I can help with?</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:18px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td class=\"col\" valign=\"top\" width=\"100%\" bgcolor=\"#F3FFCC\" style=\"background:#F3FFCC;border-top:3px solid #000000;padding:18px 20px 4px 20px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Know this</p><p style=\"margin:0 0 16px 0;font-family:Arial, Helvetica, sans-serif;font-size:15px;line-height:1.6;color:#2B2B2B;\">In California, an employer can be responsible when a non-employee, like a volunteer, harasses staff, if a supervisor knows or should have known and doesn&#x27;t take quick, appropriate action (Gov. Code 12940(j)). Most tough volunteer conversations aren&#x27;t harassment. But if one crosses the line, don&#x27;t sit on it. Write down what happened and loop in Ben the same day.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:24px 40px 0 40px;\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"border:2px solid #000000;padding:22px 24px;\"><p style=\"margin:0 0 8px 0;font-family:Arial, Helvetica, sans-serif;font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#000000;\">Your 5-minute move</p><p style=\"margin:0;font-family:Georgia, 'Times New Roman', serif;font-size:20px;line-height:1.5;color:#2B2B2B;\">Before the end of the month, take 5 minutes with each person on your team. No agenda. Ask how they&#x27;re doing, thank them for one specific thing, and ask what would help.</p></td></tr></table></td></tr><tr><td class=\"pad\" style=\"padding:26px 40px 34px 40px;font-family:Arial, Helvetica, sans-serif;font-size:14px;line-height:1.7;color:#2B2B2B;\">Questions, or something with your team you want to talk through? Reach out to Ben anytime at <a href=\"mailto:ben@pendolinogroup.com\" style=\"color:#000000;font-weight:bold;\">ben@pendolinogroup.com</a>.<br><br><span style=\"font-size:11px;color:#707070;\">Sources: <a href=\"https://afb.org/about-afb/history/helen-keller/helen-keller-quotes/helen-keller-quotes-progress\" style=\"color:#707070;\">Helen Keller (AFB)</a> &middot; <a href=\"https://www.gallup.com/workplace/713033/managers-and-team-productivity.aspx\" style=\"color:#707070;\">Gallup</a> &middot; <a href=\"https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=GOV&amp;sectionNum=12940\" style=\"color:#707070;\">Cal. Gov. Code 12940</a></span></td></tr><!--/BODY-->\n</table></td></tr></table></body></html>", "status": "ready", "inLibrary": false, "label": "Students Run LA", "createdAt": "2026-10-26T20:00:00Z", "updatedAt": "2026-10-26T20:00:00Z"}$nl$::jsonb || jsonb_build_object('clientId', cid))
    on conflict (id) do nothing;
  end if;
